/* DAWAH X — ahmad, অধ্যায় 63 · খণ্ড 63 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][63]=[[12401,12401,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ الْحَبْحَابِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏ ‏أَوْ مَهْرَهَا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَوْ ‏ ‏أَصْدَقَهَا ‏ ‏عِتْقَهَا ‏","","",""],[12402,12402,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏حَدَّثَهُمْ قَالَ ‏ ‏لَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ فِي شَيْءٍ مِنْ دُعَائِهِ ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏مَرَّةً مِنْ الدُّعَاءِ ‏ ‏إِلَّا فِي ‏ ‏الِاسْتِسْقَاءِ فَإِنَّهُ كَانَ ‏ ‏يَرْفَعُ يَدَيْهِ حَتَّى يُرَى بَيَاضُ إِبِطَيْهِ ‏","","",""],[12403,12403,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ ‏ ‏أَسْلِمْ قَالَ إِنِّي أَجِدُنِي كَارِهًا قَالَ وَإِنْ كُنْتَ كَارِهًا ‏","","",""],[12404,12404,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَسْقِي ‏ ‏أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ ‏ ‏وَأُبَيَّ بْنَ كَعْبٍ ‏ ‏وَسُهَيْلَ ابْنَ بَيْضَاءَ ‏ ‏وَنَفَرًا مِنْ أَصْحَابِهِ عِنْدَ ‏ ‏أَبِي طَلْحَةَ ‏ ‏وَأَنَا أَسْقِيهِمْ حَتَّى كَادَ الشَّرَابُ أَنْ يَأْخُذَ فِيهِمْ فَأَتَى آتٍ مِنْ الْمُسْلِمِينَ فَقَالَ أَوَمَا شَعَرْتُمْ ‏ ‏أَنَّ الْخَمْرَ قَدْ حُرِّمَتْ فَمَا قَالُوا حَتَّى نَنْظُرَ وَنَسْأَلَ فَقَالُوا يَا ‏ ‏أَنَسُ ‏ ‏اكْفِ مَا بَقِيَ فِي إِنَائِكَ قَالَ فَوَاللَّهِ مَا عَادُوا فِيهَا وَمَا هِيَ إِلَّا التَّمْرُ ‏ ‏وَالْبُسْرُ ‏ ‏وَهِيَ خَمْرُهُمْ يَوْمَئِذٍ ‏","","",""],[12405,12405,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَبَّيْكَ بِعُمْرَةٍ وَحَجٍّ ‏","","",""],[12406,12406,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الشُّرْبِ قَائِمًا ‏ ‏قُلْتُ فَالْأَكْلُ ‏ ‏قَالَ ‏ ‏ذَاكَ أَشَدُّ ‏","","",""],[12407,12407,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَيَزِيدَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏يَقْدَمُ عَلَيْكُمْ أَقْوَامٌ أَرَقُّ مِنْكُمْ أَفْئِدَةً فَقَدِمَ ‏ ‏الْأَشْعَرِيُّونَ ‏ ‏فِيهِمْ ‏ ‏أَبُو مُوسَى ‏ ‏فَجَعَلُوا لَمَّا قَدِمُوا ‏ ‏الْمَدِينَةَ ‏ ‏يَرْتَجِزُونَ ‏ ‏غَدًا نَلْقَى ‏ ‏الْأَحِبَّهْ ‏ ‏مُحَمَّدًا ‏ ‏وَحِزْبَهْ ‏","","",""],[12408,12408,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَمِعَ الْمُسْلِمُونَ ‏ ‏بِبَدْرٍ ‏ ‏وَهُوَ يُنَادِي ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا جَهْلِ بْنَ هِشَامٍ ‏ ‏يَا ‏ ‏شَيْبَةُ بْنَ رَبِيعَةَ ‏ ‏يَا ‏ ‏عُتْبَةُ بْنَ رَبِيعَةَ ‏ ‏يَا ‏ ‏أُمَيَّةُ بْنَ خَلَفٍ ‏ ‏هَلْ وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حَقًّا فَإِنِّي وَجَدْتُ مَا وَعَدَنِي رَبِّي حَقًّا قَالُوا كَيْفَ تُكَلِّمُ قَوْمًا قَدْ ‏ ‏جَيَّفُوا ‏ ‏أَوْ لَا يَسْتَطِيعُونَ أَنْ يُجِيبُوا ‏ ‏قَالَ مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ ‏","","",""],[12409,12409,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا رَجَعْنَا مِنْ غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏قَالَ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏إِنَّ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَقْوَامًا مَا قَطَعْتُمْ وَادِيًا وَلَا سِرْتُمْ مَسِيرًا إِلَّا شَرَكُوكُمْ فِيهِ قَالُوا وَهُمْ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ حَبَسَهُمْ الْعُذْرُ ‏","","",""],[12410,12410,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ وَقْتِ صَلَاةِ الصُّبْحِ ‏ ‏فَصَلَّى حِينَ طَلَعَ الْفَجْرُ ثُمَّ صَلَّى ‏ ‏الْغَدَاةَ ‏ ‏بَعْدَ مَا أَسْفَرَ ثُمَّ قَالَ أَيْنَ السَّائِلُ عَنْ وَقْتِ صَلَاةِ الصُّبْحِ مَا بَيْنَ هَذَيْنِ ‏","","",""],[12411,12411,"","","‏ ‏مَضْرُوبٌ عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَرَادُوا أَنْ يَتَحَوَّلُوا مِنْ دِيَارِهِمْ إِلَى قُرْبِ الْمَسْجِدِ ‏ ‏فَكَرِهَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُعْرَى الْمَسْجِدُ فَقَالَ يَا ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَلَا تَحْتَسِبُونَ آثَارَكُمْ فَأَقَامُوا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏أَخْطَأَ فِيهِ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَإِنَّمَا هُوَ أَنْ يُعْرُوا ‏ ‏الْمَدِينَةَ ‏ ‏فَقَالَ ‏ ‏يَحْيَى ‏ ‏الْمَسْجِدَ وَضَرَبَ عَلَيْهِ أَبِي هَاهُنَا وَقَدْ حَدَّثَنَا بِهِ فِي كِتَابِ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏","","",""],[12412,12412,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ بُكَاءَ صَبِيٍّ فِي الصَّلَاةِ ‏ ‏فَخَفَّفَ فَظَنَنَّا أَنَّهُ خَفَّفَ مِنْ أَجْلِ أُمِّهِ رَحْمَةً لِلصَّبِيِّ ‏","","",""],[12413,12413,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ أَحَدًا أَتَمَّ صَلَاةً مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا أَوْجَزَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏نَحْوَهُ مِثْلَهُ ‏","","",""],[12414,12414,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏هَلْ اتَّخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا قَالَ نَعَمْ أَخَّرَ الْعِشَاءَ لَيْلَةً إِلَى ‏ ‏شَطْرِ ‏ ‏اللَّيْلِ فَقَالَ ‏ ‏إِنَّ النَّاسَ قَدْ صَلَّوْا وَرَقَدُوا وَإِنَّكُمْ لَمْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمُوهَا فَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏خَاتَمِهِ ‏","","",""],[12415,12415,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَجِيٌّ لِرَجُلٍ حَتَّى نَعَسَ أَوْ كَادَ يَنْعَسُ بَعْضُ الْقَوْمِ ‏","","",""],[12416,12416,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ فَقَالَ ‏ ‏مَا كُنَّا نَشَاءُ أَنْ ‏ ‏نَرَاهُ مُصَلِّيًا إِلَّا رَأَيْنَاهُ وَلَا نَائِمًا إِلَّا رَأَيْنَاهُ ‏","","",""],[12417,12417,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏عَنْ كَسْبِ ‏ ‏الْحَجَّامِ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَمَهُ ‏ ‏أَبُو طَيْبَةَ ‏ ‏فَأَمَرَ لَهُ ‏ ‏بِصَاعٍ ‏ ‏مِنْ شَعِيرٍ وَكَلَّمَ ‏ ‏مَوَالِيَهُ ‏ ‏أَنْ يُخَفِّفُوا عَنْهُ مِنْ ضَرِيبَتِهِ وَقَالَ أَمْثَلُ مَا تَدَاوَيْتُمْ بِهِ ‏ ‏الْحِجَامَةُ ‏ ‏وَالْقُسْطُ ‏ ‏الْبَحْرِيُّ ‏","","",""],[12418,12418,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْبَلَ عَلَى أَصْحَابِهِ فَقَالَ ‏ ‏أَقِيمُوا صُفُوفَكُمْ وَتَرَاصُّوا فَإِنِّي أَرَاكُمْ مِنْ بَعْدِ ظَهْرِي ‏","","",""],[12419,12419,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأَنْصَارِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَادَ أَنْ يَكْتُبَ لِنَاسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِلَى ‏ ‏الْبَحْرَيْنِ ‏ ‏فَقَالُوا لَا إِلَّا أَنْ تَكْتُبَ لِإِخْوَانِنَا مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏مِثْلَهَا فَدَعَاهُمْ فَأَبَوْا قَالَ ‏ ‏أَمَا إِنَّكُمْ سَتَرَوْنَ بَعْدِي أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي ‏","","",""],[12420,12420,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ لِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَلَمْ أَسْمَعْهُ مِنْهُ ‏ ‏إِنَّ فِيكُمْ قَوْمًا يَعْبُدُونَ وَيَدْأَبُونَ حَتَّى يُعْجَبَ بِهِمْ النَّاسُ وَتُعْجِبَهُمْ نُفُوسُهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ ‏ ‏مُرُوقَ ‏ ‏السَّهْمِ ‏ ‏مِنْ ‏ ‏الرَّمِيَّةِ ‏","","",""],[12421,12421,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يَفْتَتِحُونَ الْقِرَاءَةَ ‏ ‏بِالْحَمْدِ لِلَّهِ رَبِّ الْعَالَمِينَ ‏","","",""],[12422,12422,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ قَائِمًا عَلَى الْحَيِّ أَسْقِيهِمْ مِنْ ‏ ‏فَضِيخِ ‏ ‏تَمْرٍ قَالَ فَجَاءَ رَجُلٌ فَقَالَ ‏ ‏إِنَّ الْخَمْرَ قَدْ حُرِّمَتْ قَالُوا ‏ ‏أَكْفِئْهَا ‏ ‏يَا ‏ ‏أَنَسُ ‏ ‏فَأَكْفَأْتُهَا ‏ ‏قُلْتُ مَا كَانَ شَرَابُهُمْ ‏ ‏قَالَ ‏ ‏الْبُسْرُ ‏ ‏وَالرُّطَبُ ‏ ‏و قَالَ ‏ ‏أَبُو بَكْرِ بْنُ أَنَسٍ ‏ ‏كَانَتْ خَمْرَهُمْ يَوْمَئِذٍ ‏ ‏وَأَنَسٌ ‏ ‏يَسْمَعُ فَلَمْ يُنْكِرْهُ ‏ ‏و قَالَ ‏ ‏بَعْضُ مَنْ كَانَ مَعَنَا ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏كَانَتْ خَمْرَهُمْ يَوْمَئِذٍ ‏","","",""],[12423,12423,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِرَجُلٍ وَهُوَ ‏ ‏يُهَادَى ‏ ‏بَيْنَ ابْنَيْهِ قَالُوا ‏ ‏نَذَرَ ‏ ‏أَنْ يَمْشِيَ قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَغَنِيٌّ عَنْ تَعْذِيبِ هَذَا نَفْسَهُ فَأَمَرَهُ أَنْ يَرْكَبَ ‏","","",""],[12424,12424,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَوَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏التَّفْلُ فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهُ هُوَ أَنْ ‏ ‏يُوَارِيَهُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏مِثْلَهُ وَقَالَ كَفَّارَتُهَا دَفْنُهَا ‏","","",""],[12425,12425,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ الْأَخْنَسِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مُرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَدِيَّةٍ ‏ ‏أَوْ ‏ ‏بَدَنَةٍ ‏ ‏فَقَالَ ‏ ‏ارْكَبْهَا فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهَا ‏ ‏هَدِيَّةٌ ‏ ‏أَوْ ‏ ‏بَدَنَةٌ ‏ ‏قَالَ وَإِنْ ‏","","",""],[12426,12426,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَبَحَ فَسَمَّى وَكَبَّرَ ‏","","",""],[12427,12427,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُضَحِّي بِكَبْشَيْنِ أَقْرَنَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏قَالَ قِيلَ وَرَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ قَالَ وَرَأَيْتُهُ وَاضِعًا قَدَمَهُ عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏قَالَ وَسَمَّى وَكَبَّرَ ‏","","",""],[12428,12428,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ يَهُودِيًّا ‏ ‏رَضَخَ ‏ ‏رَأْسَ امْرَأَةٍ بَيْنَ حَجَرَيْنِ فَقَتَلَهَا ‏ ‏فَرَضَخَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ بَيْنَ حَجَرَيْنِ ‏","","",""],[12429,12429,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَرَّ عَلَيْنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ نَلْعَبُ فَقَالَ ‏ ‏السَّلَامُ عَلَيْكُمْ يَا صِبْيَانُ ‏","","",""],[12430,12430,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي صَالِحٍ ‏ ‏وَكَانَ دَبَّاغًا وَكَانَ حَسَنَ الْهَيْئَةِ عِنْدَهُ أَرْبَعَةُ أَحَادِيثَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ نَاسٌ الْجَحِيمَ حَتَّى إِذَا كَانُوا ‏ ‏حُمَمًا ‏ ‏أُخْرِجُوا فَأُدْخِلُوا الْجَنَّةَ فَيَقُولُ أَهْلُ الْجَنَّةِ هَؤُلَاءِ الْجَهَنَّمِيُّونَ ‏","","",""],[12431,12431,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَبَّيْكَ بِحَجَّةٍ وَعُمْرَةٍ مَعًا ‏","","",""],[12432,12432,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ سُلَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏أَهَلَّ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحَجَّةٍ وَعُمْرَةٍ ‏","","",""],[12433,12433,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَهْلِ أَبِي الْأَسَدِ ‏ ‏عَنْ ‏ ‏بُكَيْرٍ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنَّا فِي بَيْتِ رَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى وَقَفَ فَأَخَذَ ‏ ‏بِعِضَادَةِ ‏ ‏الْبَابِ فَقَالَ ‏ ‏الْأَئِمَّةُ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏وَلَهُمْ عَلَيْكُمْ حَقٌّ وَلَكُمْ مِثْلُ ذَلِكَ مَا إِذَا اسْتُرْحِمُوا رَحِمُوا وَإِذَا حَكَمُوا عَدَلُوا وَإِذَا عَاهَدُوا وَفَّوْا فَمَنْ لَمْ يَفْعَلْ ذَلِكَ مِنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ‏","","",""],[12434,12434,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَعْدٍ ‏ ‏وَهُوَ ‏ ‏يَدْعُو بِأُصْبُعَيْنِ فَقَالَ أَحِّدْ يَا ‏ ‏سَعْدُ ‏","","",""],[12435,12435,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ قَامَتْ عَلَى أَحَدِكُمْ الْقِيَامَةُ وَفِي يَدِهِ ‏ ‏فَسْلَةٌ ‏ ‏فَلْيَغْرِسْهَا ‏","","",""],[12436,12436,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ قَالَ ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏ثَابِتًا ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَفَعَ يَدَيْهِ حَتَّى رُئِيَ بَيَاضُ إِبِطَيْهِ ‏","","",""],[12437,12437,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْحَمُ أُمَّتِي ‏ ‏أَبُو بَكْرٍ ‏ ‏وَأَشَدُّهَا فِي دِينِ اللَّهِ ‏ ‏عُمَرُ ‏ ‏وَأَصْدَقُهَا حَيَاءً ‏ ‏عُثْمَانُ ‏ ‏وَأَعْلَمُهَا بِالْحَلَالِ وَالْحَرَامِ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏وَأَقْرَؤُهَا لِكِتَابِ اللَّهِ ‏ ‏أُبَيٌّ ‏ ‏وَأَعْلَمُهَا بِالْفَرَائِضِ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏وَلِكُلِّ أُمَّةٍ أَمِينٌ وَأَمِينُ هَذِهِ الْأُمَّةِ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏","","",""],[12438,12438,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏أَيُّ اللِّبَاسِ كَانَ أَحَبَّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحِبَرَةُ ‏","","",""],[12439,12439,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِي بَحْرٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجِبْتُ لِلْمُؤْمِنِ إِنَّ اللَّهَ لَا يَقْضِي لِلْمُؤْمِنِ قَضَاءً إِلَّا كَانَ خَيْرًا لَهُ ‏ ‏أَبُو بَحْرٍ ‏ ‏اسْمُهُ ‏ ‏ثَعْلَبَةُ ‏","","",""],[12440,12440,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْمُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏خَيْرَ ‏ ‏الْبَرِيَّةِ ‏ ‏قَالَ ذَاكَ ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[12441,12441,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْمُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏خَيْرَ ‏ ‏الْبَرِيَّةِ ‏ ‏قَالَ ذَاكَ ‏ ‏إِبْرَاهِيمُ ‏ ‏أَبِي ‏","","",""],[12442,12442,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُثَنَّى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَقَدَ أَحَدُكُمْ عَنْ الصَّلَاةِ أَوْ غَفَلَ عَنْهَا فَلْيُصَلِّهَا إِذَا ذَكَرَهَا فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ { ‏أَقِمْ الصَّلَاةَ لِذِكْرِي ‏}","","",""],[12443,12443,"","","‏ ‏قَالَ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا غَزَا قَالَ ‏ ‏اللَّهُمَّ أَنْتَ ‏ ‏عَضُدِي ‏ ‏وَأَنْتَ نَصِيرِي وَبِكَ أُقَاتِلُ ‏","","",""],[12444,12444,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُضِحَ ‏ ‏لَهُ حَصِيرٌ فَصَلَّى عَلَيْهِ ‏ ‏قَالَ ‏ ‏فَقَالَ لَهُ رَجُلٌ رَأَيْتُهُ ‏ ‏يُصَلِّي الضُّحَى ‏ ‏قَالَ ‏ ‏لَمْ أَرَهُ إِلَّا ذَلِكَ الْيَوْمَ ‏","","",""],[12445,12445,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏شَهْرًا بَعْدَ الرُّكُوعِ ‏","","",""],[12446,12446,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَبْيَضِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ بَيْضَاءُ مُحَلِّقَةٌ فَأَرْجِعُ إِلَى أَهْلِي وَعَشِيرَتِي مِنْ نَاحِيَةِ ‏ ‏الْمَدِينَةِ ‏ ‏فَأَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ صَلَّى فَقُومُوا فَصَلُّوا ‏","","",""],[12447,12447,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏إِنْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُصِيبُ التَّمْرَةَ فَيَقُولُ ‏ ‏لَوْلَا أَنِّي أَخْشَى أَنَّهَا مِنْ ‏ ‏الصَّدَقَةِ ‏ ‏لَأَكَلْتُهَا ‏","","",""],[12448,12448,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي بَيْتِ ‏ ‏أُمِّ حَرامٍ ‏ ‏عَلَى بِسَاطٍ ‏","","",""],[12449,12449,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَبْلًا مَمْدُودًا بَيْنَ ‏ ‏سَارِيَتَيْنِ ‏ ‏فَقَالَ لِمَنْ هَذَا قَالُوا ‏ ‏لِحَمْنَةَ بِنْتِ جَحْشٍ ‏ ‏فَإِذَا عَجَزَتْ تَعَلَّقَتْ بِهِ فَقَالَ ‏ ‏لِتُصَلِّ مَا طَاقَتْ فَإِذَا عَجَزَتْ فَلْتَقْعُدْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[12450,12450,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏ضَخْمٌ لَا يَسْتَطِيعُ أَنْ يُصَلِّيَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَا أَسْتَطِيعُ أَنْ أُصَلِّيَ مَعَكَ فَصَنَعَ لَهُ طَعَامًا وَدَعَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَسَطُوا لَهُ حَصِيرًا ‏ ‏وَنَضَحُوهُ ‏ ‏فَصَلَّى عَلَيْهِ رَكْعَتَيْنِ ‏ ‏فَقَالَ ‏ ‏لَهُ رَجُلٌ مِنْ آلِ ‏ ‏الْجَارُودِ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى قَالَ ‏ ‏مَا رَأَيْتُهُ صَلَّاهَا ‏ ‏إِلَّا يَوْمَئِذٍ ‏","","",""],[12451,12451,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثُمَامَةُ بْنُ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَهُ أَصْحَابُهُ ذَاتَ لَيْلَةٍ فَخَرَجَ فَصَلَّى بِهِمْ فَخَفَّفَ ثُمَّ دَخَلَ بَيْتَهُ فَأَطَالَ ثُمَّ خَرَجَ فَصَلَّى بِهِمْ فَخَفَّفَ ثُمَّ دَخَلَ بَيْتَهُ فَأَطَالَ فَلَمَّا أَصْبَحَ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏صَلَّيْتَ فَجَعَلْتَ تُطِيلُ إِذَا دَخَلْتَ وَتُخَفِّفُ إِذَا خَرَجْتَ قَالَ مِنْ أَجْلِكُمْ مَا فَعَلْتُ ‏","","",""],[12452,12452,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏وَبَهْزٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِأُبَيٍّ ‏ ‏إِنَّ اللَّهَ أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ قَالَ ‏ ‏أُبَيٌّ ‏ ‏آللَّهُ سَمَّانِي لَكَ قَالَ اللَّهُ سَمَّاكَ لِي ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ فَجَعَلَ يَبْكِي ‏","","",""],[12453,12453,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ فِي رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلِحْيَتِهِ عِشْرُونَ شَعَرَةً بَيْضَاءَ ‏","","",""],[12454,12454,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَتَّابٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ فِيمَا اسْتَطَعْتُ ‏","","",""],[12455,12455,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْسَنَ النَّاسِ وَأَشْجَعَ النَّاسِ وَأَجْوَدَ النَّاسِ كَانَ فَزَعٌ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَخَرَجَ النَّاسُ قِبَلَ الصَّوْتِ فَاسْتَقْبَلَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ سَبَقَهُمْ فَاسْتَبْرَأَ الْفَزَعَ عَلَى فَرَسٍ ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏عُرْيٍ مَا عَلَيْهِ ‏ ‏سَرْجٌ ‏ ‏فِي عُنُقِهِ السَّيْفُ فَقَالَ ‏ ‏لَمْ ‏ ‏تُرَاعُوا ‏ ‏وَقَالَ لِلْفَرَسِ وَجَدْنَاهُ بَحْرًا ‏ ‏أَوْ إِنَّهُ لَبَحْرٌ ‏","","",""],[12456,12456,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنِ ‏ ‏أَبِي عِصَامٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَنَفَّسُ فِي الْإِنَاءِ ثَلَاثًا وَيَقُولُ هُوَ أَهْنَأُ ‏ ‏وَأَمْرَأُ ‏ ‏وَأَبْرَأُ ‏","","",""],[12457,12457,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَزْرَةُ بْنُ ثَابِتٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏كَانَ يَتَنَفَّسُ فِي الْإِنَاءِ مَرَّتَيْنِ أَوْ ثَلَاثًا ‏ ‏قَالَ ‏ ‏وَزَعَمَ ‏ ‏أَنَسٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَنَفَّسُ فِي الْإِنَاءِ ثَلَاثًا ‏","","",""],[12458,12458,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ عَلَى نِسَائِهِ فِي غُسْلٍ وَاحِدٍ ‏","","",""],[12459,12459,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ عَلَى نِسَائِهِ فِي لَيْلَةٍ وَاحِدَةٍ فِي غُسْلٍ وَاحِدٍ ‏","","",""],[12460,12460,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَرْوَانَ الْأَصْغَرَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏قَدِمَ مِنْ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَ ‏ ‏أَهْلَلْتَ ‏ ‏فَقَالَ ‏ ‏أَهْلَلْتُ ‏ ‏بِمَا أَهَلَّ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ فَإِنِّي ‏ ‏لَوْلَا أَنَّ مَعِي ‏ ‏الْهَدْيَ ‏ ‏لَأَحْلَلْتُ ‏","","",""],[12461,12461,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لَا يَقْطَعُهَا ‏ ‏قَالَ ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏","","",""],[12462,12462,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏بَعْدَ الظُّهْرِ فَقَامَ ‏ ‏يُصَلِّي الْعَصْرَ فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ ذَكَرْنَا تَعْجِيلَ الصَّلَاةِ ‏ ‏أَوْ ذَكَرَهَا ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تِلْكَ صَلَاةُ الْمُنَافِقِينَ تِلْكَ صَلَاةُ الْمُنَافِقِينَ يَجْلِسُ أَحَدُهُمْ حَتَّى إِذَا اصْفَرَّتْ الشَّمْسُ وَكَانَتْ بَيْنَ قَرْنَيْ الشَّيْطَانِ ‏ ‏أَوْ عَلَى قَرْنِ الشَّيْطَانِ ‏ ‏قَامَ فَنَقَرَ أَرْبَعًا لَا يَذْكُرُ اللَّهَ فِيهَا إِلَّا قَلِيلًا ‏","","",""],[12463,12463,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رُؤْيَا الْمُؤْمِنِ ‏ ‏أَوْ الْمُسْلِمِ ‏ ‏جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[12464,12464,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏مَكَّةَ ‏ ‏عَامَ الْفَتْحِ وَعَلَى رَأْسِهِ ‏ ‏الْمِغْفَرُ ‏ ‏فَلَمَّا نَزَعَهُ جَاءَهُ رَجُلٌ وَقَالَ ‏ ‏ابْنُ خَطَلٍ ‏ ‏مُتَعَلِّقٌ بِأَسْتَارِ ‏ ‏الْكَعْبَةِ ‏ ‏فَقَالَ اقْتُلُوهُ ‏ ‏قَالَ ‏ ‏مَالِكٌ ‏ ‏وَلَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ مُحْرِمًا وَاللَّهُ أَعْلَمُ ‏","","",""],[12465,12465,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ ‏ ‏وَتَزَوَّجَهَا ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏ثَابِتٌ ‏ ‏مَا أَصْدَقَهَا قَالَ ‏ ‏نَفْسَهَا أَعْتَقَهَا وَتَزَوَّجَهَا ‏","","",""],[12466,12466,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَرْبَعًا وَصَلَّى الْعَصْرَ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[12467,12467,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى أَزْوَاجِهِ وَسَوَّاقٌ يَسُوقُ بِهِنَّ يُقَالُ لَهُ ‏ ‏أَنْجَشَةُ ‏ ‏فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏يَا ‏ ‏أَنْجَشَةُ ‏ ‏رُوَيْدَكَ سَوْقَكَ ‏ ‏بِالْقَوَارِيرِ ‏ ‏قَالَ ‏ ‏أَبُو قِلَابَةَ ‏ ‏تَكَلَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَلِمَةٍ لَوْ تَكَلَّمَ بِهَا بَعْضُكُمْ لَعِبْتُمُوهَا عَلَيْهِ ‏ ‏يَعْنِي قَوْلَهُ سَوْقَكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[12468,12468,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَبِي عُثْمَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو رَجَاءٍ ‏ ‏مَوْلَى ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ أَنَا أُحَدِّثُكُمْ حَدِيثَ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏إِيَّايَ ‏ ‏حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏نَفَرًا ‏ ‏مِنْ ‏ ‏عُكْلٍ ‏ ‏ثَمَانِيَةً قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَايَعُوهُ عَلَى الْإِسْلَامِ ‏ ‏فَاسْتَوْخَمُوا ‏ ‏الْأَرْضَ ‏ ‏فَسَقِمَتْ ‏ ‏أَجْسَامُهُمْ فَشَكَوْا ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَلَا تَخْرُجُونَ مَعَ رَاعِينَا فِي إِبِلِهِ فَتُصِيبُونَ مِنْ أَبْوَالِهَا وَأَلْبَانِهَا قَالُوا بَلَى فَخَرَجُوا فَشَرِبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا فَصَحُّوا فَقَتَلُوا ‏ ‏الرَّاعِيَ ‏ ‏وَأَطْرَدُوا النَّعَمَ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْسَلَ فِي ‏ ‏آثَارِهِمْ ‏ ‏فَأُدْرِكُوا فَجِيءَ بِهِمْ فَأَمَرَ بِهِمْ فَقُطِّعَتْ أَيْدِيهِمْ وَأَرْجُلُهُمْ ‏ ‏وَسُمِرَتْ ‏ ‏أَعْيُنُهُمْ ثُمَّ ‏ ‏نُبِذُوا ‏ ‏فِي الشَّمْسِ حَتَّى مَاتُوا ‏","","",""],[12469,12469,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏عَنْ الثُّومِ فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ شَيْئًا فَلَا يَقْرَبَنَّ ‏ ‏أَوْ لَا يُصَلِّيَنَّ مَعَنَا ‏","","",""],[12470,12470,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَرُّوا بِجِنَازَةٍ فَأَثْنَوْا عَلَيْهَا خَيْرًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَبَتْ وَجَبَتْ وَجَبَتْ وَمَرُّوا بِجَنَازَةٍ فَأَثْنَوْا عَلَيْهَا شَرًّا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَبَتْ وَجَبَتْ وَجَبَتْ فَقَالَ ‏ ‏عُمَرُ ‏ ‏فِدَاكَ أَبِي وَأُمِّي مُرَّ بِجَنَازَةٍ فَأُثْنِيَ عَلَيْهَا خَيْرًا فَقُلْتَ وَجَبَتْ وَجَبَتْ وَجَبَتْ وَمُرَّ بِجَنَازَةٍ فَأُثْنِيَ عَلَيْهَا شَرًّا فَقُلْتَ وَجَبَتْ وَجَبَتْ وَجَبَتْ فَقَالَ ‏ ‏مَنْ أَثْنَيْتُمْ عَلَيْهِ خَيْرًا وَجَبَتْ لَهُ الْجَنَّةُ وَمَنْ أَثْنَيْتُمْ عَلَيْهِ شَرًّا وَجَبَتْ لَهُ النَّارُ أَنْتُمْ شُهَدَاءُ اللَّهِ فِي الْأَرْضِ أَنْتُمْ شُهَدَاءُ اللَّهِ فِي الْأَرْضِ أَنْتُمْ شُهَدَاءُ اللَّهِ فِي الْأَرْضِ ‏","","",""],[12471,12471,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مُرَّ بِجِنَازَةٍ فَأَثْنَى الْقَوْمُ خَيْرًا فَقَالَ وَجَبَتْ ثُمَّ مُرَّ بِجَنَازَةٍ أُخْرَى فَأُثْنِيَ عَلَيْهَا شَرًّا فَقَالَ وَجَبَتْ فَقَالُوا قُلْتَ لِهَذَا وَجَبَتْ وَلِهَذَا وَجَبَتْ قَالَ ‏ ‏شَهَادَةُ الْقَوْمِ وَالْمُؤْمِنُونَ شُهَدَاءُ اللَّهِ فِي الْأَرْضِ ‏","","",""],[12472,12472,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏وَعَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ ‏ ‏بِغَلَسٍ ‏ ‏ثُمَّ قَالَ ‏ ‏اللَّهُ أَكْبَرُ خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ قَالَ فَخَرَجُوا يَسْعَوْنَ فِي السِّكَكِ وَهُمْ يَقُولُونَ ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏قَالَ فَظَهَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِمْ فَقَتَلَ مُقَاتِلَتَهُمْ ‏ ‏وَسَبَى ‏ ‏ذَرَارِيَّهُمْ ‏ ‏وَصَارَتْ ‏ ‏صَفِيَّةُ ‏ ‏لِدِحْيَةَ الْكَلْبِيِّ ‏ ‏ثُمَّ صَارَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدُ فَتَزَوَّجَهَا وَجَعَلَ ‏ ‏صَدَاقَهَا ‏ ‏عِتْقَهَا ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏يَا ‏ ‏أَبَا مُحَمَّدٍ ‏ ‏أَنْتَ سَأَلْتَ ‏ ‏أَنَسًا ‏ ‏مَا أَمْهَرَهَا فَقَالَ لَكَ ‏ ‏أَنَسٌ ‏ ‏أَمْهَرَهَا نَفْسَهَا فَضَحِكَ ‏ ‏ثَابِتٌ ‏ ‏وَقَالَ نَعَمْ ‏","","",""],[12473,12473,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ وَنَقَشَ فِيهِ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي قَدْ ‏ ‏اتَّخَذْتُ خَاتَمًا مِنْ فِضَّةٍ وَنَقَشْتُ فِيهِ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ فَلَا تَنْقُشُوا عَلَيْهِ ‏","","",""],[12474,12474,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرِّجَالَ عَنْ ‏ ‏الْمُزَعْفَرِ ‏","","",""],[12475,12475,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى الدِّمَشْقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَكْحُولٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ مَتَى نَدَعُ ‏ ‏الِائْتِمَارَ بِالْمَعْرُوفِ وَالنَّهْيَ عَنْ الْمُنْكَرِ قَالَ ‏ ‏إِذَا ظَهَرَ فِيكُمْ مَا ظَهَرَ فِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏إِذَا كَانَتْ الْفَاحِشَةُ فِي كِبَارِكُمْ وَالْمُلْكُ فِي صِغَارِكُمْ وَالْعِلْمُ فِي رُذَالِكُمْ ‏","","",""],[12476,12476,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي الْمَسِيرِ وَكَانَ حَادٍ ‏ ‏يَحْدُو بِنِسَائِهِ ‏ ‏أَوْ سَائِقٌ ‏ ‏قَالَ فَكَانَ نِسَاؤُهُ يَتَقَدَّمْنَ بَيْنَ يَدَيْهِ فَقَالَ يَا ‏ ‏أَنْجَشَةُ ‏ ‏وَيْحَكَ ‏ ‏ارْفُقْ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[12477,12477,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى بْنُ عَبْدِ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَجَعَلَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ رَكْعَتَيْنِ حَتَّى رَجَعَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فَقُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏كَمْ أَقَامَ ‏ ‏قَالَ ‏ ‏عَشْرًا ‏","","",""],[12478,12478,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏فَسَمِعْتُهُ يَقُولُ ‏ ‏لَبَّيْكَ عُمْرَةً وَحَجَّةً ‏","","",""],[12479,12479,"","","‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مِنْ ‏ ‏خَيْبَرَ ‏ ‏أَنَا ‏ ‏وَأَبُو طَلْحَةَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَفِيَّةُ ‏ ‏رَدِيفَتُهُ قَالَ فَعَثَرَتْ نَاقَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصُرِعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصُرِعَتْ ‏ ‏صَفِيَّةُ ‏ ‏قَالَ فَاقْتَحَمَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ جَعَلَنِي اللَّهُ فِدَاكَ قَالَ أَشُكُّ قَالَ ذَاكَ أَمْ لَا أَضُرِرْتَ قَالَ لَا عَلَيْكَ الْمَرْأَةَ قَالَ فَأَلْقَى ‏ ‏أَبُو طَلْحَةَ ‏ ‏عَلَى وَجْهِهِ الثَّوْبَ فَانْطَلَقَ إِلَيْهَا فَمَدَّ ثَوْبَهُ عَلَيْهَا ثُمَّ أَصْلَحَ لَهَا رَحْلَهَا فَرَكِبْنَا ثُمَّ اكْتَنَفْنَاهُ أَحَدُنَا عَنْ يَمِينِهِ وَالْآخَرُ عَنْ شِمَالِهِ فَلَمَّا أَشْرَفْنَا عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏أَوْ كُنَّا بِظَهْرِ ‏ ‏الْحَرَّةِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آيِبُونَ عَابِدُونَ تَائِبُونَ لِرَبِّنَا حَامِدُونَ فَلَمْ يَزَلْ يَقُولُهُنَّ حَتَّى دَخَلْنَا ‏ ‏الْمَدِينَةَ ‏","","",""],[12480,12480,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ حَسَّانَ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فَدَعَا بِإِنَاءٍ وَفِيهِ ثَلَاثُ ضِبَابٍ حَدِيدٍ وَحَلْقَةٌ مِنْ حَدِيدٍ فَأُخْرِجَ مِنْ غِلَافٍ أَسْوَدَ وَهُوَ دُونَ الرُّبُعِ وَفَوْقَ نِصْفِ الرُّبُعِ فَأَمَرَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏فَجُعِلَ لَنَا فِيهِ مَاءٌ فَأُتِينَا بِهِ فَشَرِبْنَا وَصَبَبْنَا عَلَى رُءُوسِنَا وَوُجُوهِنَا وَصَلَّيْنَا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12481,12481,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏عَنْ رَفْعِ الْأَيْدِي فَقَالَ قَامَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْجُمُعَةِ بَعْضُ الْمُسْلِمِينَ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏قَحَطَ ‏ ‏الْمَطَرُ ‏ ‏وَأَجْدَبَتْ ‏ ‏الْأَرْضُ هَلَكَ الْمَالُ قَالَ فَاسْتَسْقَى فَرَفَعَ يَدَيْهِ حَتَّى رَأَيْتُ بَيَاضَ إِبْطَيْهِ وَمَا نَرَى فِي السَّمَاءِ سَحَابَةً فَقَامَ فَصَلَّى حَتَّى جَعَلَ يَهُمُّ الْقَرِيبُ الدَّارِ الرُّجُوعَ إِلَى أَهْلِهِ مِنْ شِدَّةِ الْمَطَرِ قَالَ فَمَكَثْنَا سَبْعًا فَلَمَّا كَانَتْ الْجُمُعَةُ قَالُوا يَا رَسُولَ اللَّهِ تَهَدَّمَتْ الْبُيُوتُ وَاحْتَبَسَ ‏ ‏الرُّكْبَانُ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا قَالَ فَتَكَشَّفَتْ عَنْ ‏ ‏الْمَدِينَةِ ‏","","",""],[12482,12482,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَرَجَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَلَقَّتْهُ ‏ ‏الْأَنْصَارُ ‏ ‏بَيْنَهُمْ فَقَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏إِنِّي لَأُحِبُّكُمْ إِنَّ ‏ ‏الْأَنْصَارَ ‏ ‏قَدْ قَضَوْا مَا عَلَيْهِمْ وَبَقِيَ الَّذِي عَلَيْكُمْ فَأَحْسِنُوا إِلَى مُحْسِنِهِمْ وَتَجَاوَزُوا عَنْ مُسِيئِهِمْ ‏","","",""],[12483,12483,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏غَدَاةٍ ‏ ‏قَرَّةٍ ‏ ‏أَوْ بَارِدَةٍ ‏ ‏فَإِذَا ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَالْأَنْصَارُ ‏ ‏يَحْفِرُونَ ‏ ‏الْخَنْدَقَ ‏ ‏فَقَالَ ‏ ‏اللَّهُمَّ إِنَّ الْخَيْرَ خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏فَأَجَابُوهُ ‏ ‏نَحْنُ الَّذِينَ بَايَعُوا ‏ ‏مُحَمَّدًا ‏ ‏عَلَى الْجِهَادِ مَا بَقِينَا أَبَدًا ‏","","",""],[12484,12484,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَعْطَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ غَنَائِمِ ‏ ‏حُنَيْنٍ ‏ ‏عُيَيْنَةَ ‏ ‏وَالْأَقْرَعَ ‏ ‏وَغَيْرَهُمَا فَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏أَيُعْطِي غَنَائِمَنَا مَنْ ‏ ‏تَقْطُرُ ‏ ‏سُيُوفُنَا مِنْ دِمَائِهِمْ ‏ ‏أَوْ ‏ ‏تَقْطُرُ ‏ ‏دِمَاؤُهُمْ مِنْ سُيُوفِنَا ‏ ‏فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا ‏ ‏الْأَنْصَارَ ‏ ‏فَقَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَمَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالدُّنْيَا وَتَذْهَبُونَ ‏ ‏بِمُحَمَّدٍ ‏ ‏إِلَى دِيَارِكُمْ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَوْ سَلَكَ النَّاسُ وَادِيًا وَسَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ ‏ ‏شِعْبَ ‏ ‏الْأَنْصَارِ ‏ ‏الْأَنْصَارُ ‏ ‏كَرِشِي ‏ ‏وَعَيْبَتِي ‏ ‏وَلَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏","","",""],[12485,12485,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فَقَرَّبَتْ إِلَيْهِ سَمْنًا وَتَمْرًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعِيدُوا سَمْنَكُمْ فِي سِقَائِكُمْ وَتَمْرَكُمْ فِي وِعَائِكُمْ فَإِنِّي صَائِمٌ ثُمَّ قَامَ فَصَلَّى فِي نَاحِيَةِ الْبَيْتِ فَصَلَّيْنَا بِصَلَاتِهِ ثُمَّ دَعَا ‏ ‏لِأُمِّ سُلَيْمٍ ‏ ‏وَأَهْلِهَا ثُمَّ قَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ لِي ‏ ‏خُوَيْصَّةً ‏ ‏قَالَ وَمَا هِيَ قَالَتْ ‏ ‏أَنَسٌ ‏ ‏قَالَ فَمَا تَرَكَ يَوْمَئِذٍ مِنْ خَيْرِ آخِرَةٍ وَلَا دُنْيَا إِلَّا دَعَا بِهِ مِنْ قَوْلِهِ ‏ ‏اللَّهُمَّ ارْزُقْهُ مَالًا وَوَلَدًا وَبَارِكْ لَهُ فِيهِمْ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَنَسٌ ‏ ‏حَدَّثَتْنِي ابْنَتِي أَنَّهُ دُفِنَ مِنْ صُلْبِي عِشْرُونَ وَمِائَةٌ وَنَيِّفٌ وَإِنِّي لَمِنْ أَكْثَرِ ‏ ‏الْأَنْصَارِ ‏ ‏مَالًا ‏","","",""],[12486,12486,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏اسْتَشَارَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَخْرَجَهُ إِلَى ‏ ‏بَدْرٍ ‏ ‏فَأَشَارَ عَلَيْهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏ثُمَّ اسْتَشَارَ ‏ ‏عُمَرَ ‏ ‏فَأَشَارَ عَلَيْهِ ‏ ‏عُمَرُ ‏ ‏ثُمَّ اسْتَشَارَهُمْ فَقَالَ بَعْضُ ‏ ‏الْأَنْصَارِ ‏ ‏إِيَّاكُمْ يُرِيدُ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ قَائِلُ ‏ ‏الْأَنْصَارِ ‏ ‏تَسْتَشِيرُنَا يَا نَبِيَّ اللَّهِ إِنَّا لَا نَقُولُ لَكَ كَمَا قَالَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏لِمُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏اذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ وَلَكِنْ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَوْ ضَرَبْتَ أَكْبَادَهَا إِلَى ‏ ‏بَرْكٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏إِلَى ‏ ‏بَرْكِ الْغِمَادِ ‏ ‏لَاتَّبَعْنَاكَ ‏","","",""],[12487,12487,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ يَعْنِي الْأَنْصَارِيَّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِدَاءَ صَبِيٍّ وَهُوَ فِي الصَّلَاةِ ‏ ‏فَخَفَّفَ فَظَنَنَّا أَنَّهُ إِنَّمَا فَعَلَ ذَلِكَ رَحْمَةً لِلصَّبِيِّ إِذْ عَلِمَ أَنَّ أُمَّهُ مَعَهُ فِي الصَّلَاةِ ‏","","",""],[12488,12488,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ سُئِلَ ‏ ‏اخْتَضَبَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَمْ يَشِنْهُ الشَّيْبُ ‏","","",""],[12489,12489,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْخُلُ عَلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏وَلَهَا ابْنٌ مِنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏يُكْنَى ‏ ‏أَبَا عُمَيْرٍ ‏ ‏وَكَانَ يُمَازِحُهُ فَدَخَلَ عَلَيْهِ فَرَآهُ حَزِينًا فَقَالَ ‏ ‏مَالِي أَرَى ‏ ‏أَبَا عُمَيْرٍ ‏ ‏حَزِينًا فَقَالُوا مَاتَ ‏ ‏نُغَرُهُ ‏ ‏الَّذِي كَانَ يَلْعَبُ بِهِ قَالَ فَجَعَلَ يَقُولُ ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏","","",""],[12490,12490,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَلَدَتْ غُلَامًا مِنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏فَبَعَثَتْ بِهِ مَعَ ابْنِهَا ‏ ‏أَنَسٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَنَّكَهُ ‏","","",""],[12491,12491,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ فَشَقَّ عَلَيْهِ حَتَّى عُرِفَ ذَاكَ فِي وَجْهِهِ فَحَكَّهُ وَقَالَ إِنَّ أَحَدَكُمْ ‏ ‏أَوْ الْمَرْءَ ‏ ‏إِذَا قَامَ إِلَى الصَّلَاةِ فَإِنَّهُ يُنَاجِي رَبَّهُ عَزَّ وَجَلَّ ‏ ‏أَوْ رَبَّهُ ‏ ‏بَيْنَهُ وَبَيْنَ الْقِبْلَةِ فَلْيَبْزُقْ إِذَا بَزَقَ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ وَأَوْمَأَ هَكَذَا كَأَنَّهُ فِي ثَوْبِهِ ‏ ‏قَالَ ‏ ‏وَكُنَّا نَقُولُ ‏ ‏لِحُمَيْدٍ ‏ ‏فَيَقُولُ ‏ ‏سُبْحَانَ اللَّهِ مَنْ هُوَ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا يَزِيدُنَا عَلَيْهِ ‏","","",""],[12492,12492,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ أَسْرَعَ الْمَشْيَ فَانْتَهَى إِلَى الْقَوْمِ وَقَدْ انْبَهَرَ فَقَالَ حِينَ قَامَ فِي الصَّلَاةِ ‏ ‏الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ فَلَمَّا قَضَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ قَالَ مَنْ الْمُتَكَلِّمُ ‏ ‏أَوْ مَنْ الْقَائِلُ ‏ ‏قَالَ فَسَكَتَ الْقَوْمُ فَقَالَ مَنْ الْمُتَكَلِّمُ ‏ ‏أَوْ مَنْ الْقَائِلُ ‏ ‏فَإِنَّهُ قَالَ خَيْرًا ‏ ‏أَوْ لَمْ يَقُلْ بَأْسًا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي انْتَهَيْتُ إِلَى الصَّفِّ وَقَدْ انْبَهَرْتُ ‏ ‏أَوْ ‏ ‏حَفَزَنِي ‏ ‏النَّفَسُ ‏ ‏قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ رَأَيْتُ اثْنَيْ عَشَرَ مَلَكًا ‏ ‏يَبْتَدِرُونَهَا ‏ ‏أَيُّهُمْ يَرْفَعُهَا ثُمَّ قَالَ إِذَا جَاءَ أَحَدُكُمْ إِلَى الصَّلَاةِ فَلْيَمْشِ عَلَى ‏ ‏هِينَتِهِ ‏ ‏فَلْيُصَلِّ مَا أَدْرَكَ وَيَقْضِ مَا سَبَقَهُ ‏","","",""],[12493,12493,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏نَادَى رَجُلٌ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَالْتَفَتَ إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ لَمْ أَعْنِكَ إِنَّمَا دَعَوْتُ فُلَانًا قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[12494,12494,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏هَلْ اتَّخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا قَالَ نَعَمْ أَخَّرَ لَيْلَةً صَلَاةَ الْعِشَاءِ الْآخِرَةِ إِلَى قُرْبٍ مِنْ ‏ ‏شَطْرِ ‏ ‏اللَّيْلِ فَلَمَّا صَلَّى أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ ‏ ‏النَّاسُ قَدْ صَلَّوْا وَنَامُوا وَلَمْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمُوهَا قَالَ ‏ ‏أَنَسٌ ‏ ‏كَأَنِّي أَنْظُرُ الْآنَ إِلَى ‏ ‏وَبِيصِ ‏ ‏خَاتَمِهِ ‏","","",""],[12495,12495,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ وَقْتِ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏فَصَلَّى حِينَ طَلَعَ الْفَجْرُ ثُمَّ أَسْفَرَ بِهِمْ حَتَّى أَسْفَرَ فَقَالَ أَيْنَ السَّائِلُ عَنْ وَقْتِ صَلَاةِ الْغَدَاةِ قَالَ مَا بَيْنَ هَذَيْنِ وَقْتٌ ‏","","",""],[12496,12496,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي الْمَغْرِبَ ثُمَّ يَنْطَلِقُ الْمُنْطَلِقُ مِنَّا إِلَى ‏ ‏بَنِي سَلِمَةَ ‏ ‏وَهُوَ يَرَى مَوَاقِعَ نَبْلِهِ ‏","","",""],[12497,12497,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَزِيدَ وَهُوَ أَبُو سَلَمَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏أَصَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَعْلَيْهِ قَالَ نَعَمْ ‏","","",""],[12498,12498,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسٌ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ أُمَّةٍ أَمِينًا وَإِنَّ أَمِينَنَا أَيُّهَا الْأُمَّةُ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏","","",""],[12499,12499,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ عَلَى نِسَائِهِ فِي لَيْلَةٍ وَاحِدَةٍ بِغُسْلٍ وَاحِدٍ ‏","","",""],[12500,12500,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَحِّي بِكَبْشَيْنِ أَقْرَنَيْنِ يَطَأُ عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏وَيَذْبَحُهُمَا بِيَدِهِ وَيُسَمِّي وَيُكَبِّرُ ‏","","",""],[12501,12501,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي إِسْحَاقَ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسٌ ‏ ‏أَقْبَلْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏وَأَبُو طَلْحَةَ ‏ ‏وَصَفِيَّةُ ‏ ‏رَدِيفَتُهُ ‏ ‏عَلَى نَاقَتِهِ فَبَيْنَمَا نَحْنُ نَسِيرُ إِذْ ‏ ‏عَثَرَتْ ‏ ‏نَاقَةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصُرِعَ ‏ ‏وَصُرِعَتْ ‏ ‏الْمَرْأَةُ فَاقْتَحَمَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏عَنْ نَاقَتِهِ قَالَ فَقَالَ يَا نَبِيَّ اللَّهِ هَلْ ضَرَّكَ شَيْءٌ قَالَ لَا عَلَيْكَ بِالْمَرْأَةِ فَأَلْقَى ‏ ‏أَبُو طَلْحَةَ ‏ ‏ثَوْبَهُ عَلَى وَجْهِهِ ثُمَّ قَصَدَ الْمَرْأَةَ ‏ ‏فَسَدَلَ ‏ ‏الثَّوْبَ عَلَيْهَا فَقَامَتْ فَشَدَّ لَهُمَا عَلَى ‏ ‏رَاحِلَتِهِمَا ‏ ‏فَرَكِبَا وَرَكِبْنَا نَسِيرُ حَتَّى إِذَا كُنَّا بِظَهْرِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏آيِبُونَ ‏ ‏تَائِبُونَ لِرَبِّنَا حَامِدُونَ فَلَمْ يَزَلْ يَقُولُ ذَلِكَ حَتَّى قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏","","",""],[12502,12502,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ سَلَامٍ ‏ ‏بَلَغَهُ مَقْدَمُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَأَتَاهُ فَسَأَلَهُ عَنْ أَشْيَاءَ قَالَ إِنِّي سَائِلُكَ عَنْ أَشْيَاءَ لَا يَعْلَمُهَا إِلَّا نَبِيٌّ قَالَ مَا أَوَّلُ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ وَمَا أَوَّلُ طَعَامٍ يَأْكُلُهُ أَهْلُ الْجَنَّةِ وَمَا بَالُ الْوَلَدِ يَنْزِعُ إِلَى أَبِيهِ وَالْوَلَدِ يَنْزِعُ إِلَى أُمِّهِ قَالَ أَخْبَرَنِي بِهِنَّ ‏ ‏جِبْرِيلُ ‏ ‏آنِفًا ‏ ‏قَالَ ‏ ‏ابْنُ سَلَامٍ ‏ ‏فَذَلِكَ عَدُوُّ ‏ ‏الْيَهُودِ ‏ ‏مِنْ الْمَلَائِكَةِ قَالَ أَمَّا ‏ ‏أَوَّلُ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ فَنَارٌ تَحْشُرُهُمْ مِنْ الْمَشْرِقِ إِلَى الْمَغْرِبِ وَأَوَّلُ طَعَامٍ يَأْكُلُهُ أَهْلُ الْجَنَّةِ زِيَادَةُ كَبِدِ حُوتٍ وَأَمَّا الْوَلَدُ فَإِذَا سَبَقَ ‏ ‏مَاءُ ‏ ‏الرَّجُلِ ‏ ‏مَاءَ ‏ ‏الْمَرْأَةِ نَزَعَ الْوَلَدَ وَإِذَا سَبَقَ ‏ ‏مَاءُ ‏ ‏الْمَرْأَةِ ‏ ‏مَاءَ ‏ ‏الرَّجُلِ نَزَعَتْ الْوَلَدَ ‏","","",""],[12503,12503,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ ‏ ‏وَيُوتِرَ ‏ ‏الْإِقَامَةَ ‏ ‏فَحَدَّثْتُ ‏ ‏بِهِ ‏ ‏أَيُّوبَ ‏ ‏فَقَالَ ‏ ‏إِلَّا الْإِقَامَةَ ‏","","",""],[12504,12504,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ لِي ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَلَمْ أَسْمَعْهُ مِنْهُ ‏ ‏إِنَّ ‏ ‏فِيكُمْ قَوْمًا يَعْبُدُونَ وَيَدْأَبُونَ ‏ ‏يَعْنِي يُعْجِبُونَ النَّاسَ وَتُعْجِبُهُمْ أَنْفُسُهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏","","",""],[12505,12505,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنِّي لَقَائِمٌ عَلَى الْحَيِّ أَسْقِيهِمْ مِنْ ‏ ‏فَضِيخٍ ‏ ‏لَهُمْ إِذْ جَاءَ رَجُلٌ فَقَالَ ‏ ‏إِنَّهَا حُرِّمَتْ الْخَمْرُ فَقَالُوا ‏ ‏أَكْفِئْهَا ‏ ‏يَا ‏ ‏أَنَسُ ‏ ‏فَأَكْفَأْتُهَا ‏ ‏فَقُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏مَا هِيَ ‏ ‏قَالَ ‏ ‏بُسْرٌ ‏ ‏وَرُطَبٌ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرِ بْنُ أَنَسٍ ‏ ‏كَانَتْ خَمْرَهُمْ يَوْمَئِذٍ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ قَالَ ذَلِكَ أَيْضًا ‏","","",""],[12506,12506,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ ‏ ‏سَعِيدُ بْنُ يَزِيدَ ‏ ‏أَخْبَرَنَا قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَنَسِ بْنِ مَالِكٍ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَفْتِحُ الْقِرَاءَةَ بْ ‏ { ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏} ‏أَوْ بْ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏فَقَالَ ‏ ‏إِنَّكَ لَتَسْأَلُنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ ‏","","",""],[12507,12507,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ قَصْرِ الصَّلَاةِ فَقَالَ سَافَرْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏فَصَلَّى بِنَا رَكْعَتَيْنِ حَتَّى رَجَعْنَا فَسَأَلْتُهُ هَلْ أَقَامَ فَقَالَ نَعَمْ أَقَمْنَا ‏ ‏بِمَكَّةَ ‏ ‏عَشْرًا ‏","","",""],[12508,12508,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏الْمَدِينَةَ ‏ ‏آخَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُ وَبَيْنَ ‏ ‏سَعْدِ بْنِ الرَّبِيعِ ‏ ‏فَقَالَ أُقَاسِمُكَ مَالِي نِصْفَيْنِ وَلِي امْرَأَتَانِ فَأُطَلِّقُ إِحْدَاهُمَا فَإِذَا انْقَضَتْ عِدَّتُهَا فَتَزَوَّجْهَا فَقَالَ بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ دُلُّونِي عَلَى السُّوقِ فَدَلُّوهُ فَانْطَلَقَ فَمَا رَجَعَ إِلَّا وَمَعَهُ شَيْءٌ مِنْ ‏ ‏أَقِطٍ ‏ ‏وَسَمْنٍ قَدْ اسْتَفْضَلَهُ فَرَآهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ ذَلِكَ وَعَلَيْهِ ‏ ‏وَضَرٌ ‏ ‏مِنْ صُفْرَةٍ فَقَالَ ‏ ‏مَهْيَمْ ‏ ‏قَالَ تَزَوَّجْتُ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏مَا ‏ ‏أَصْدَقْتَهَا ‏ ‏قَالَ نَوَاةً مِنْ ذَهَبٍ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏أَوْ وَزْنَ نَوَاةٍ مِنْ ذَهَبٍ ‏ ‏فَقَالَ ‏ ‏أَوْلِمْ ‏ ‏وَلَوْ بِشَاةٍ ‏","","",""],[12509,12509,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ أَبُو الْأَسْوَدِ الْعَمِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏هَوَازِنَ ‏ ‏جَاءَتْ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏بِالصِّبْيَانِ وَالنِّسَاءِ وَالْإِبِلِ وَالنَّعَمِ فَجَعَلُوهُمْ صُفُوفًا يُكَثِّرُونَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا الْتَقَوْا وَلَّى الْمُسْلِمُونَ مُدْبِرِينَ كَمَا قَالَ اللَّهُ عَزَّ وَجَلَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا عِبَادَ اللَّهِ ‏ ‏أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ فَهَزَمَ اللَّهُ الْمُشْرِكِينَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَلَمْ يَضْرِبُوا بِسَيْفٍ وَلَمْ يَطْعَنُوا بِرُمْحٍ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ مَنْ قَتَلَ كَافِرًا فَلَهُ ‏ ‏سَلَبُهُ ‏ ‏فَقَتَلَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَوْمَئِذٍ عِشْرِينَ رَجُلًا وَأَخَذَ ‏ ‏أَسْلَابَهُمْ ‏ ‏قَالَ وَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏يَا رَسُولَ اللَّهِ ضَرَبْتُ رَجُلًا عَلَى ‏ ‏حَبْلِ الْعَاتِقِ ‏ ‏وَعَلَيْهِ دِرْعٌ فَأُجْهِضْتُ عَنْهُ فَانْظُرْ مَنْ أَخَذَهَا فَقَامَ رَجُلٌ فَقَالَ أَنَا أَخَذْتُهَا فَأَرْضِهِ مِنْهَا وَأَعْطِنِيهَا قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُسْأَلُ شَيْئًا إِلَّا أَعْطَاهُ أَوْ سَكَتَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏لَا وَاللَّهِ لَا ‏ ‏يُفِيئُهَا ‏ ‏اللَّهُ عَلَى أَسَدٍ مِنْ أُسْدِهِ ‏ ‏وَيُعْطِيكَهَا فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ صَدَقَ ‏ ‏عُمَرُ ‏ ‏قَالَ وَكَانَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏مَعَهَا خِنْجَرٌ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏مَا هَذَا مَعَكِ قَالَتْ اتَّخَذْتُهُ إِنْ دَنَا مِنِّي بَعْضُ الْمُشْرِكِينَ أَنْ ‏ ‏أَبْعَجَ ‏ ‏بِهِ بَطْنَهُ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا تَسْمَعُ مَا تَقُولُ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ اقْتُلْ مَنْ بَعْدَنَا مِنْ الطُّلَقَاءِ انْهَزَمُوا بِكَ قَالَ إِنَّ اللَّهَ قَدْ كَفَانَا وَأَحْسَنَ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ أَخْضَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِشَامُ بْنُ زَيْدِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏حُنَيْنٍ ‏ ‏وَجَمَعَتْ ‏ ‏هَوَزِانُ ‏ ‏وَغَطَفَانُ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمْعًا كَثِيرًا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي عَشْرَةِ آلَافٍ أَوْ أَكْثَرَ وَمَعَهُ الطُّلَقَاءُ فَجَاءُوا بِالنَّعَمِ وَالذُّرِّيَّةِ فَذَكَرَ الْحَدِيثَ ‏","","",""],[12510,12510,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَزُورُ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَلَهَا ابْنٌ صَغِيرٌ يُقَالُ لَهُ ‏ ‏أَبُو عُمَيْرٍ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَا ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏ ‏قَالَ ‏ ‏نُغَرٌ ‏ ‏يَلْعَبُ بِهِ ‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَزُورُ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏أَحْيَانًا وَيَتَحَدَّثُ عِنْدَهَا فَتُدْرِكُهُ الصَّلَاةُ فَيُصَلِّي عَلَى بِسَاطٍ وَهُوَ حَصِيرٌ ‏ ‏يَنْضَحُهُ ‏ ‏بِالْمَاءِ ‏","","",""],[12511,12511,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أُسَيْدَ بْنَ حُضَيْرٍ ‏ ‏وَعَبَّادَ بْنَ بِشْرٍ ‏ ‏كَانَا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي لَيْلَةٍ ظَلْمَاءَ ‏ ‏حِنْدِسٍ ‏ ‏قَالَ فَلَمَّا خَرَجَا مِنْ عِنْدِهِ ‏ ‏أَضَاءَتْ عَصَا أَحَدِهِمَا ‏ ‏فَكَانَا يَمْشِيَانِ بِضَوْئِهَا فَلَمَّا تَفَرَّقَا أَضَاءَتْ عَصَا هَذَا وَعَصَا هَذَا ‏","","",""],[12512,12512,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ قَامَتْ السَّاعَةُ وَبِيَدِ أَحَدِكُمْ ‏ ‏فَسِيلَةٌ ‏ ‏فَإِنْ اسْتَطَاعَ أَنْ لَا يَقُومَ حَتَّى يَغْرِسَهَا فَلْيَفْعَلْ ‏","","",""],[12513,12513,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ ‏ ‏جَدِّي ‏ ‏دَارَ الْإِمَارَةِ فَإِذَا دَجَاجَةٌ ‏ ‏مَصْبُورَةٌ ‏ ‏تُرْمَى فَكُلَّمَا أَصَابَهَا سَهْمٌ صَاحَتْ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تُصْبَرَ ‏ ‏الْبَهَائِمُ ‏","","",""],[12514,12514,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَرَأَيْتُ قَصْرًا مِنْ ذَهَبٍ فَقُلْتُ لِمَنْ هَذَا قَالُوا لِفَتًى مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَظَنَنْتُهُ لِي فَإِذَا هُوَ ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مَنَعَنِي يَا ‏ ‏أَبَا حَفْصٍ ‏ ‏أَنْ أَدْخُلَهُ إِلَّا مَا أَعْرِفُ مِنْ غَيْرَتِكَ قَالَ قَالَ يَا رَسُولَ اللَّهِ مَنْ كُنْتُ أَغَارُ عَلَيْهِ فَإِنِّي لَمْ أَكُنْ أَغَارُ عَلَيْكَ ‏","","",""],[12515,12515,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا فِي الْمَسْجِدِ وَأَصْحَابُهُ مَعَهُ إِذْ جَاءَ أَعْرَابِيٌّ فَبَالَ فِي الْمَسْجِدِ فَقَالَ أَصْحَابُهُ ‏ ‏مَهْ ‏ ‏مَهْ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُزْرِمُوهُ ‏ ‏دَعُوهُ ثُمَّ دَعَاهُ فَقَالَ لَهُ إِنَّ هَذِهِ الْمَسَاجِدَ لَا تَصْلُحُ لِشَيْءٍ مِنْ الْقَذَرِ وَالْبَوْلِ ‏ ‏وَالْخَلَاءِ ‏ ‏أَوْ كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا هِيَ لِقِرَاءَةِ الْقُرْآنِ وَذِكْرِ اللَّهِ وَالصَّلَاةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِرَجُلٍ مِنْ الْقَوْمِ قُمْ فَأْتِنَا بِدَلْوٍ مِنْ مَاءٍ ‏ ‏فَشُنَّهُ ‏ ‏عَلَيْهِ فَأَتَاهُ بِدَلْوٍ مِنْ مَاءٍ ‏ ‏فَشَنَّهُ ‏ ‏عَلَيْهِ ‏","","",""],[12516,12516,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ قَائِمًا ‏ ‏يُصَلِّي فِي بَيْتِهِ فَجَاءَ رَجُلٌ فَاطَّلَعَ فِي الْبَيْتِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏فِي بَيْتِهِ ‏ ‏فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَهْمًا مِنْ ‏ ‏كِنَانَتِهِ ‏ ‏فَسَدَّدَهُ نَحْوَ عَيْنَيْهِ حَتَّى انْصَرَفَ ‏","","",""],[12517,12517,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجِيءُ ‏ ‏الدَّجَّالُ ‏ ‏فَيَطَأُ ‏ ‏الْأَرْضَ إِلَّا ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةَ ‏ ‏فَيَأْتِي ‏ ‏الْمَدِينَةَ ‏ ‏فَيَجِدُ بِكُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْ ‏ ‏نِقَابِهَا ‏ ‏صُفُوفًا مِنْ الْمَلَائِكَةِ فَيَأْتِي ‏ ‏سَبْخَةَ الْجَرْفِ ‏ ‏فَيَضْرِبُ ‏ ‏رِوَاقَهُ ‏ ‏فَتَرْجُفُ ‏ ‏الْمَدِينَةُ ‏ ‏ثَلَاثَ رَجَفَاتٍ فَيَخْرُجُ إِلَيْهِ كُلُّ مُنَافِقٍ وَمُنَافِقَةٍ ‏","","",""],[12518,12518,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏","","",""],[12519,12519,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ فَقَالَ الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ فَلَمَّا قَضَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ قَالَ أَيُّكُمْ الْقَائِلُ كَذَا وَكَذَا قَالَ ‏ ‏فَأَرَمَّ ‏ ‏الْقَوْمُ قَالَ فَأَعَادَهَا ثَلَاثَ مَرَّاتٍ فَقَالَ رَجُلٌ أَنَا قُلْتُهَا وَمَا أَرَدْتُ بِهَا إِلَّا الْخَيْرَ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏ابْتَدَرَهَا ‏ ‏اثْنَا عَشَرَ مَلَكًا فَمَا دَرَوْا كَيْفَ يَكْتُبُونَهَا حَتَّى سَأَلُوا رَبَّهُمْ عَزَّ وَجَلَّ قَالَ اكْتُبُوهَا كَمَا قَالَ عَبْدِي ‏","","",""],[12520,12520,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا أَسِيرُ فِي الْجَنَّةِ فَإِذَا أَنَا بِنَهَرٍ حَافَّتَاهُ ‏ ‏قِبَابُ ‏ ‏الدُّرِّ الْمُجَوَّفِ قَالَ فَقُلْتُ مَا هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَ رَبُّكَ عَزَّ وَجَلَّ قَالَ فَضَرَبْتُ بِيَدِي فَإِذَا طِينُهُ مِسْكٌ ‏ ‏أَذْفَرُ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏الْمُجَوَّفُ ‏","","",""],[12521,12521,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏شَهْرًا ثُمَّ تَرَكَهُ ‏","","",""],[12522,12522,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏و حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ كَالْكَلْبِ وَلَا يَبْزُقْ بَيْنَ يَدَيْهِ وَلَا ‏ ‏عَنْ يَمِينِهِ فَإِنَّمَا يُنَاجِي رَبَّهُ وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ ‏","","",""],[12523,12523,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏الزُّبَيْرَ ‏ ‏وَعَبْدَ الَّرحْمَنِ بْنَ عَوْفٍ ‏ ‏شَكَوَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقَمْلَ فَاسْتَأْذَنَا فِي غَزَاةٍ لَهُمَا ‏ ‏فَرَخَّصَ لَهُمَا فِي قَمِيصِ الْحَرِيرِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَرَأَيْتُ عَلَى كُلِّ وَاحِدٍ مِنْهُمَا قَمِيصًا مِنْ حَرِيرٍ ‏","","",""],[12524,12524,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَتَى السَّاعَةُ قَالَ وَيْلَكَ وَمَا أَعْدَدْتَ لِلسَّاعَةِ قَالَ مَا أَعْدَدْتُ لَهَا شَيْئًا إِلَّا أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّكَ مَعَ مَنْ أَحْبَبْتَ قَالَ قَالَ أَصْحَابُهُ نَحْنُ كَذَلِكَ قَالَ نَعَمْ وَأَنْتُمْ كَذَلِكَ قَالَ فَفَرِحُوا يَوْمَئِذٍ فَرَحًا شَدِيدًا قَالَ فَمَرَّ غُلَامٌ ‏ ‏لِلْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏وَكَانَ مِنْ ‏ ‏أَقْرَانِي ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ يُؤَخَّرْ هَذَا فَلَنْ يُدْرِكَهُ ‏ ‏الْهَرَمُ ‏ ‏حَتَّى تَقُومَ السَّاعَةُ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏فَفَرِحْنَا بِهِ يَوْمَئِذٍ فَرَحًا شَدِيدًا ‏","","",""],[12525,12525,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏أَخَضَبَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَمْ يَبْلُغْ ذَلِكَ إِنَّمَا كَانَ شَيْءٌ فِي صُدْغَيْهِ ‏ ‏وَلَكِنْ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏خَضَبَ ‏ ‏بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏","","",""],[12526,12526,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ يَهُودِيًّا مَرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابِهِ فَقَالَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَرَدَّ عَلَيْهِ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا قَالَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَأُخِذَ الْيَهُودِيُّ فَجِيءَ بِهِ فَاعْتَرَفَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُدُّوا عَلَيْهِمْ مَا قَالُوا ‏","","",""],[12527,12527,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَوْ أَنَّ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيَيْنِ مِنْ مَالٍ لَابْتَغَى وَادِيًا ثَالِثًا وَلَا يَمْلَأُ جَوْفَ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا التُّرَابُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏ثُمَّ يَتُوبُ اللَّهُ عَلَى مَنْ تَابَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيَيْنِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[12528,12528,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَحَدَّثَنِي ‏ ‏بَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَهْرَمُ ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَيَشِبُّ مِنْهُ اثْنَتَانِ الْحِرْصُ عَلَى الْمَالِ وَالْحِرْصُ عَلَى الْعُمُرِ ‏","","",""],[12529,12529,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ نَخْلًا ‏ ‏لِأُمِّ مُبَشِّرٍ ‏ ‏امْرَأَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ مَنْ غَرَسَ هَذَا الْغَرْسَ أَمُسْلِمٌ أَمْ كَافِرٌ قَالُوا مُسْلِمٌ قَالَ ‏ ‏لَا يَغْرِسُ مُسْلِمٌ غَرْسًا فَيَأْكُلُ مِنْهُ إِنْسَانٌ أَوْ دَابَّةٌ أَوْ طَائِرٌ إِلَّا كَانَ لَهُ صَدَقَةً ‏","","",""],[12530,12530,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَوَّامِ الْقَطَّانُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَهُوَ ‏ ‏عِمْرَانُ بْنُ دَاوَرَ ‏ ‏وَهُوَ أَعْمَى ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَخْلَفَ ‏ ‏ابْنَ أُمِّ مَكْتُومٍ ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏مَرَّتَيْنِ ‏ ‏يُصَلِّي بِهِمْ وَهُوَ أَعْمَى ‏","","",""],[12531,12531,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْتَجِمُ ‏ ‏ثَلَاثًا وَاحِدَةً عَلَى ‏ ‏كَاهِلِهِ ‏ ‏وَاثْنَتَيْنِ عَلَى ‏ ‏الْأَخْدَعَيْنِ ‏","","",""],[12532,12532,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏كَيْفَ كَانَتْ قِرَاءَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ يَمُدُّ صَوْتَهُ مَدًّا ‏","","",""],[12533,12533,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ قَوْلٍ لَا يُسْمَعُ وَعَمَلٍ لَا يُرْفَعُ وَقَلْبٍ لَا يَخْشَعُ وَعِلْمٍ لَا يَنْفَعُ ‏","","",""],[12534,12534,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْبَرَصِ ‏ ‏وَالْجُنُونِ ‏ ‏وَالْجُذَامِ ‏ ‏وَمِنْ سَيِّئِ ‏ ‏الْأَسْقَامِ ‏","","",""],[12535,12535,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَمُرُّ بِالتَّمْرَةِ فَمَا يَمْنَعُهُ مِنْ أَخْذِهَا إِلَّا مَخَافَةُ أَنْ تَكُونَ ‏ ‏صَدَقَةً ‏","","",""],[12536,12536,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ جَارِيَةً وُجِدَ رَأْسُهَا بَيْنَ حَجَرَيْنِ فَقِيلَ لَهَا مَنْ فَعَلَ بِكِ هَذَا أَفُلَانٌ أَفُلَانٌ حَتَّى سَمَّى الْيَهُودِيَّ فَأَوْمَأَتْ بِرَأْسِهَا نَعَمْ فَأُخِذَ الْيَهُودِيُّ فَاعْتَرَفَ ‏ ‏فَأَمَرَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرُضَّ رَأْسُهُ بِالْحِجَارَةِ ‏","","",""],[12537,12537,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَعَدَنِي رَبِّي عَزَّ وَجَلَّ أَنْ يُدْخِلَ مِنْ أُمَّتِي الْجَنَّةَ مِائَةَ أَلْفٍ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ زِدْنَا قَالَ لَهُ وَهَكَذَا وَأَشَارَ بِيَدِهِ قَالَ يَا نَبِيَّ اللَّهِ زِدْنَا فَقَالَ وَهَكَذَا وَأَشَارَ بِيَدِهِ قَالَ يَا نَبِيَّ اللَّهِ زِدْنَا فَقَالَ وَهَكَذَا فَقَالَ ‏ ‏عُمَرُ ‏ ‏قَطْكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏قَالَ مَا لَنَا وَلَكَ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏قَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَادِرٌ أَنْ يُدْخِلَ النَّاسَ الْجَنَّةَ كُلَّهُمْ بِحَفْنَةٍ وَاحِدَةٍ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏ ‏عُمَرُ ‏","","",""],[12538,12538,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ الْعَبْدُ بِخَيْرٍ مَا لَمْ يَسْتَعْجِلْ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ يَسْتَعْجِلُ قَالَ يَقُولُ دَعَوْتُ رَبِّي فَلَمْ يَسْتَجِبْ لِي ‏","","",""],[12539,12539,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا ‏","","",""],[12540,12540,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏بُعِثْتُ أَنَا وَالسَّاعَةُ كَهَاتَيْنِ وَرَفَعَ أُصْبُعَيْهِ السَّبَّابَةَ وَالْوُسْطَى فَضَّلَ إِحْدَاهُمَا عَلَى الْأُخْرَى ‏","","",""],[12541,12541,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏كُنَّا نُهِينَا فِي الْقُرْآنِ أَنْ نَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ شَيْءٍ قَالَ وَكَانَ يُعْجِبُنَا أَنْ يَجِيءَ الرَّجُلُ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏الْعَاقِلُ يَسْأَلُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَجَاءَ رَجُلٌ فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏أَتَانَا رَسُولُكَ وَزَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ اللَّهَ عَزَّ وَجَلَّ أَرْسَلَكَ قَالَ صَدَقَ قَالَ فَمَنْ خَلَقَ السَّمَاءَ قَالَ اللَّهُ قَالَ فَمَنْ خَلَقَ الْأَرْضَ قَالَ اللَّهُ قَالَ فَمَنْ نَصَبَ هَذِهِ الْجِبَالَ قَالَ اللَّهُ قَالَ فَبِالَّذِي خَلَقَ السَّمَاءَ وَخَلَقَ الْأَرْضَ وَنَصَبَ الْجِبَالَ ‏ ‏آللَّهُ أَرْسَلَكَ قَالَ نَعَمْ قَالَ وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا خَمْسَ صَلَوَاتٍ فِي يَوْمِنَا وَلَيْلَتِنَا قَالَ صَدَقَ قَالَ فَبِالَّذِي أَرْسَلَكَ ‏ ‏آللَّهُ أَمَرَكَ بِهَذَا قَالَ نَعَمْ قَالَ وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا زَكَاةً فِي أَمْوَالِنَا قَالَ صَدَقَ قَالَ فَبِالَّذِي أَرْسَلَكَ ‏ ‏آللَّهُ أَمَرَكَ بِهَذَا قَالَ نَعَمْ قَالَ وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا صَوْمَ شَهْرِ رَمَضَانَ فِي سَنَتِنَا ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَالَ صَدَقَ قَالَ فَبِالَّذِي أَرْسَلَكَ ‏ ‏آللَّهُ أَمَرَكَ بِهَذَا قَالَ نَعَمْ وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا الْحَجَّ مَنْ اسْتَطَاعَ إِلَيْهِ سَبِيلًا قَالَ صَدَقَ قَالَ فَبِالَّذِي أَرْسَلَكَ ‏ ‏آللَّهُ أَمَرَكَ بِهَذَا قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏ثُمَّ وَلَّى ‏ ‏ثُمَّ قَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَا أَزِيدُ وَلَا أَنْتَقِصُ مِنْهُنَّ شَيْئًا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَئِنْ صَدَقَ لَيَدْخُلَنَّ الْجَنَّةَ ‏","","",""],[12542,12542,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي رَمَضَانَ فَجِئْتُ فَقُمْتُ خَلْفَهُ قَالَ وَجَاءَ رَجُلٌ فَقَامَ إِلَى جَنْبِي ثُمَّ جَاءَ آخَرُ حَتَّى كُنَّا ‏ ‏رَهْطًا ‏ ‏فَلَمَّا أَحَسَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّا خَلْفَهُ ‏ ‏تَجَوَّزَ ‏ ‏فِي الصَّلَاةِ ثُمَّ قَامَ فَدَخَلَ مَنْزِلَهُ فَصَلَّى صَلَاةً لَمْ يُصَلِّهَا عِنْدَنَا قَالَ فَلَمَّا أَصْبَحْنَا قَالَ قُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏أَفَطِنْتَ ‏ ‏بِنَا اللَّيْلَةَ قَالَ نَعَمْ فَذَاكَ الَّذِي حَمَلَنِي عَلَى الَّذِي صَنَعْتُ قَالَ ثُمَّ أَخَذَ ‏ ‏يُوَاصِلُ ‏ ‏وَذَاكَ فِي آخِرِ الشَّهْرِ قَالَ فَأَخَذَ رِجَالٌ ‏ ‏يُوَاصِلُونَ ‏ ‏مِنْ أَصْحَابِهِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَالُ رِجَالٍ ‏ ‏يُوَاصِلُونَ ‏ ‏إِنَّكُمْ لَسْتُمْ مِثْلِي أَمَا وَاللَّهِ لَوْ مُدَّ لِي الشَّهْرُ ‏ ‏لَوَاصَلْتُ ‏ ‏وِصَالًا ‏ ‏يَدَعُ ‏ ‏الْمُتَعَمِّقُونَ ‏ ‏تَعَمُّقَهُمْ ‏","","",""],[12543,12543,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا هُوَ إِلَّا أَنَا وَأُمِّي ‏ ‏وَأُمُّ حَرَامٍ ‏ ‏خَالَتِي قَالَ فَقَالَ ‏ ‏قُومُوا ‏ ‏فَلِأُصَلِّي لَكُمْ فِي غَيْرِ وَقْتِ صَلَاةٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ فَصَلَّى بِنَا صَلَاةً ‏ ‏قَالَ رَجُلٌ مِنْ الْقَوْمِ ‏ ‏لِثَابِتٍ ‏ ‏أَيْنَ جَعَلَ ‏ ‏أَنَسًا ‏ ‏قَالَ جَعَلَهُ عَلَى يَمِينِهِ قَالَ ثُمَّ دَعَا لَنَا أَهْلَ الْبَيْتِ بِكُلِّ خَيْرٍ مِنْ خَيْرِ الدُّنْيَا وَالْآخِرَةِ قَالَ قَالَتْ أُمِّي يَا رَسُولَ اللَّهِ ‏ ‏خُوَيْدِمُكَ ‏ ‏ادْعُ اللَّهَ لَهُ ثُمَّ قَالَ فَدَعَا لِي بِكُلِّ خَيْرٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏وَكَانَ فِي آخِرِ مَا دَعَا بِهِ اللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ وَبَارِكْ لَهُ فِيهِ ‏","","",""],[12544,12544,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏وَحَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وُلِدَ لِي اللَّيْلَةَ غُلَامٌ فَسَمَّيْتُهُ بِاسْمِ أَبِي ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ثُمَّ دَفَعَهُ إِلَى ‏ ‏أُمِّ سَيْفٍ ‏ ‏امْرَأَةِ قَيْنٍ يُقَالُ لَهُ ‏ ‏أَبُو سَيْفٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ فَانْطَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِيهِ وَانْطَلَقْتُ مَعَهُ فَانْتَهَيْتُ إِلَى ‏ ‏أَبِي سَيْفٍ ‏ ‏وَهُوَ يَنْفُخُ ‏ ‏بِكِيرِهِ ‏ ‏وَقَدْ امْتَلَأَ الْبَيْتُ دُخَانًا قَالَ فَأَسْرَعْتُ الْمَشْيَ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقُلْتُ يَا ‏ ‏أَبَا سَيْفٍ ‏ ‏جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَمْسَكَ قَالَ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا بِالصَّبِيِّ فَضَمَّهُ إِلَيْهِ قَالَ ‏ ‏أَنَسٌ ‏ ‏فَلَقَدْ رَأَيْتُهُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَكِيدُ بِنَفْسِهِ قَالَ فَدَمَعَتْ عَيْنَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَدْمَعُ الْعَيْنُ وَيَحْزَنُ الْقَلْبُ وَلَا نَقُولُ إِلَّا مَا ‏ ‏يُرْضِي رَبَّنَا عَزَّ وَجَلَّ وَاللَّهِ إِنَّا بِكَ يَا ‏ ‏إِبْرَاهِيمُ ‏ ‏لَمَحْزُونُونَ ‏","","",""],[12545,12545,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏عَمِّي ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏أَنَسُ بْنُ النَّضْرِ ‏ ‏سُمِّيتُ بِهِ ‏ ‏لَمْ يَشْهَدْ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏قَالَ فَشَقَّ عَلَيْهِ وَقَالَ فِي أَوَّلِ مَشْهَدٍ شَهِدَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غِبْتُ عَنْهُ لَئِنْ أَرَانِي اللَّهُ مَشْهَدًا فِيمَا بَعْدُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَرَيَنَّ اللَّهُ مَا أَصْنَعُ قَالَ ‏ ‏فَهَابَ ‏ ‏أَنْ يَقُولَ غَيْرَهَا قَالَ فَشَهِدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏قَالَ فَاسْتَقْبَلَ ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏قَالَ فَقَالَ لَهُ ‏ ‏أَنَسٌ ‏ ‏يَا ‏ ‏أَبَا عَمْرٍو ‏ ‏أَيْنَ قَالَ ‏ ‏وَاهًا ‏ ‏لِرِيحِ الْجَنَّةِ أَجِدُهُ دُونَ ‏ ‏أُحُدٍ ‏ ‏قَالَ فَقَاتَلَهُمْ حَتَّى قُتِلَ فَوُجِدَ فِي جَسَدِهِ بِضْعٌ وَثَمَانُونَ مِنْ ضَرْبَةٍ وَطَعْنَةٍ وَرَمْيَةٍ قَالَ فَقَالَتْ أُخْتُهُ عَمَّتِي ‏ ‏الرُّبَيِّعُ بِنْتُ النَّضْرِ ‏ ‏فَمَا عَرَفْتُ أَخِي إِلَّا ‏ ‏بِبَنَانِهِ ‏ ‏وَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى ‏ ‏نَحْبَهُ ‏ ‏وَمِنْهُمْ مَنْ يَنْتَظِرُ وَمَا بَدَّلُوا تَبْدِيلًا ‏} ‏قَالَ فَكَانُوا يَرَوْنَ أَنَّهَا نَزَلَتْ فِيهِ وَفِي أَصْحَابِهِ ‏","","",""],[12546,12546,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسٌ ‏ ‏إِنِّي لَقَاعِدٌ عِنْدَ الْمِنْبَرِ يَوْمَ الْجُمُعَةِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ إِذْ قَالَ بَعْضُ أَهْلِ الْمَسْجِدِ يَا رَسُولَ اللَّهِ حُبِسَ الْمَطَرُ هَلَكَتْ الْمَوَاشِي ادْعُ اللَّهَ أَنْ يَسْقِيَنَا قَالَ ‏ ‏أَنَسٌ ‏ ‏فَرَفَعَ يَدَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا أَرَى فِي السَّمَاءِ مِنْ سَحَابٍ فَأُلِّفَ بَيْنَ السَّحَابِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فَأَلَّفَ اللَّهُ بَيْنَ السَّحَابِ ‏ ‏فَوَأَلْنَا ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏سَعَيْنَا ‏ ‏حَتَّى رَأَيْتُ الرَّجُلَ الشَّدِيدَ تَهُمُّهُ نَفْسُهُ أَنْ يَأْتِيَ أَهْلَهُ فَمُطِرْنَا سَبْعًا وَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فِي الْجُمُعَةِ الْمُقْبِلَةِ إِذْ قَالَ بَعْضُ أَهْلِ الْمَسْجِدِ يَا رَسُولَ اللَّهِ تَهَدَّمَتْ الْبُيُوتُ حُبِسَ ‏ ‏السِّفَارُ ‏ ‏ادْعُ اللَّهَ عَزَّ وَجَلَّ أَنْ يَرْفَعَهَا عَنَّا قَالَ فَرَفَعَ يَدَيْهِ فَقَالَ ‏ ‏اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا قَالَ فَتَقَوَّرَ مَا فَوْقَ رَأْسِنَا مِنْهَا حَتَّى كَأَنَّا فِي ‏ ‏إِكْلِيلٍ ‏ ‏يُمْطَرُ مَا حَوْلَنَا وَلَا نُمْطَرُ ‏","","",""],[12547,12547,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ الْأَنْصَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَدَحٍ مِنْ مَاءٍ ‏ ‏فَتَوَضَّأَ قَالَ فَقُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ عِنْدَ كُلِّ صَلَاةٍ قَالَ نَعَمْ قَالَ قُلْتُ فَأَنْتُمْ قَالَ كُنَّا نُصَلِّي الصَّلَوَاتِ بِوُضُوءٍ وَاحِدٍ قَالَ ثُمَّ سَأَلْتُهُ بَعْدَ ذَلِكَ فَقَالَ مَا لَمْ ‏ ‏نُحْدِثْ ‏","","",""],[12548,12548,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ أَنْ يَبْنِيَ الْمَسْجِدَ ‏ ‏يُصَلِّي فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ ‏","","",""],[12549,12549,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الْمُخْتَارِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَنَسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ كَانَ هُوَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُمُّهُ وَخَالَتُهُ ‏ ‏فَصَلَّى بِهِمْ فَجُعِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ يَمِينِهِ وَأُمُّهُ وَخَالَتُهُ خَلْفَهُمَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُخْتَارِ ‏ ‏أَشَبَّ مِنِّي ‏","","",""],[12550,12550,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ لِضُرٍّ أَصَابَهُ فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلْ اللَّهُمَّ أَحْيِنِي مَا كَانَتْ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتْ الْوَفَاةُ خَيْرًا لِي ‏","","",""],[12551,12551,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏خَدَمْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرَ سِنِينَ وَمَا كُلُّ أَمْرِي كَمَا يُحِبُّ صَاحِبِي أَنْ يَكُونَ مَا قَالَ لِي فِيهَا أُفٍّ وَلَا قَالَ لِي لِمَ فَعَلْتَ هَذَا وَأَلَّا فَعَلْتَ هَذَا ‏","","",""],[12552,12552,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَهَاشِمٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏خَدَمْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا حَتَّى إِذَا رَأَيْتُ أَنِّي قَدْ فَرَغْتُ مِنْ خِدْمَتِهِ قُلْتُ يَقِيلُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجْتُ إِلَى صِبْيَانٍ يَلْعَبُونَ قَالَ فَجِئْتُ أَنْظُرُ إِلَى لَعِبِهِمْ قَالَ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ عَلَى الصِّبْيَانِ وَهُمْ يَلْعَبُونَ فَدَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَعَثَنِي إِلَى حَاجَةٍ لَهُ فَذَهَبْتُ فِيهَا وَجَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏فَيْءٍ ‏ ‏حَتَّى أَتَيْتُهُ وَاحْتَبَسْتُ عَنْ أُمِّي عَنْ الْإِتْيَانِ الَّذِي كُنْتُ ‏ ‏آتِيهَا فِيهِ فَلَمَّا أَتَيْتُهَا قَالَتْ مَا حَبَسَكَ قُلْتُ بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ لَهُ قَالَتْ وَمَا هِيَ قُلْتُ هُوَ سِرٌّ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَاحْفَظْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِرَّهُ ‏ ‏قَالَ ‏ ‏ثَابِتٌ ‏ ‏قَالَ ‏ ‏لِي ‏ ‏أَنَسٌ ‏ ‏لَوْ حَدَّثْتُ بِهِ أَحَدًا مِنْ النَّاسِ ‏ ‏أَوْ لَوْ كُنْتُ مُحَدِّثًا بِهِ ‏ ‏لَحَدَّثْتُكَ بِهِ يَا ‏ ‏ثَابِتُ ‏","","",""],[12553,12553,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏قَالَ ‏ ‏صَارَتْ ‏ ‏صَفِيَّةُ ‏ ‏لِدِحْيَةَ ‏ ‏فِي مَقْسَمِهِ وَجَعَلُوا يَمْدَحُونَهَا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَيَقُولُونَ مَا رَأَيْنَا فِي ‏ ‏السَّبْيِ ‏ ‏مِثْلَهَا قَالَ فَبَعَثَ إِلَى ‏ ‏دِحْيَةَ ‏ ‏فَأَعْطَاهُ بِهَا مَا أَرَادَ ثُمَّ دَفَعَهَا إِلَى أُمِّي فَقَالَ أَصْلِحِيهَا قَالَ ثُمَّ خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏خَيْبَرَ ‏ ‏حَتَّى إِذَا جَعَلَهَا فِي ظَهْرِهِ نَزَلَ ثُمَّ ضَرَبَ عَلَيْهَا الْقُبَّةَ فَلَمَّا أَصْبَحَ قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ عِنْدَهُ فَضْلُ زَادٍ فَلْيَأْتِنَا بِهِ قَالَ فَجَعَلَ الرَّجُلُ يَجِيءُ بِفَضْلِ التَّمْرِ وَفَضْلِ السَّوِيقِ وَبِفَضْلِ السَّمْنِ حَتَّى جَعَلُوا مِنْ ذَلِكَ سَوَادًا ‏ ‏حَيْسًا ‏ ‏فَجَعَلُوا يَأْكُلُونَ مِنْ ذَلِكَ ‏ ‏الْحَيْسِ ‏ ‏وَيَشْرَبُونَ مِنْ حِيَاضٍ إِلَى جَنْبِهِمْ مِنْ مَاءِ السَّمَاءِ قَالَ فَقَالَ ‏ ‏أَنَسٌ ‏ ‏فَكَانَتْ تِلْكَ ‏ ‏وَلِيمَةَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهَا وَانْطَلَقْنَا حَتَّى إِذَا رَأَيْنَا جُدُرَ ‏ ‏الْمَدِينَةِ ‏ ‏هَشِشْنَا إِلَيْهَا فَرَفَعْنَا ‏ ‏مَطِيَّنَا ‏ ‏وَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَطِيَّتَهُ ‏ ‏قَالَ ‏ ‏وَصَفِيَّةُ ‏ ‏خَلْفَهُ قَدْ أَرْدَفَهَا قَالَ ‏ ‏فَعَثَرَتْ ‏ ‏مَطِيَّةُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏فَصُرِعَ ‏ ‏وَصُرِعَتْ ‏ ‏قَالَ فَلَيْسَ أَحَدٌ مِنْ النَّاسِ يَنْظُرُ إِلَيْهِ وَلَا إِلَيْهَا حَتَّى قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَتَرَهَا قَالَ فَأَتَيْنَاهُ فَقَالَ لَمْ تُضَرَّ قَالَ فَدَخَلَ ‏ ‏الْمَدِينَةَ ‏ ‏فَخَرَجَ جَوَارِي نِسَائِهِ يَتَرَاءَيْنَهَا وَيَشْمَتْنَ ‏ ‏بِصَرْعَتِهَا ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلِيمَةً مَا فِيهَا خُبْزٌ وَلَا لَحْمٌ حِينَ صَارَتْ ‏ ‏صَفِيَّةُ ‏ ‏لِدِحْيَةَ الْكَلْبِيِّ ‏ ‏فِي مَقْسَمِهِ فَجَعَلُوا يَمْدَحُونَهَا فَذَكَرَ مَعْنَاهُ ‏","","",""],[12554,12554,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏ثَابِتٍ ‏ ‏عَنِ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا انْقَضَتْ عِدَّةُ ‏ ‏زَيْنَبَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِزَيْدٍ ‏ ‏اذْهَبْ فَاذْكُرْهَا عَلَيَّ قَالَ فَانْطَلَقَ حَتَّى أَتَاهَا قَالَ وَهِيَ تُخَمِّرُ عَجِينَهَا فَلَمَّا رَأَيْتُهَا عَظُمَتْ فِي صَدْرِي حَتَّى مَا أَسْتَطِيعُ أَنْ أَنْظُرَ إِلَيْهَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَهَا فَوَلَّيْتُهَا ظَهْرِي وَرَكَضْتُ عَلَى عَقِبَيَّ فَقُلْتُ يَا ‏ ‏زَيْنَبُ ‏ ‏أَبْشِرِي أَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُكِ قَالَتْ مَا أَنَا بِصَانِعَةٍ شَيْئًا حَتَّى أُؤَامِرَ رَبِّي عَزَّ وَجَلَّ فَقَامَتْ إِلَى مَسْجِدِهَا وَنَزَلَ ‏ ‏يَعْنِي الْقُرْآنَ ‏ ‏وَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ عَلَيْهَا بِغَيْرِ إِذْنٍ قَالَ وَلَقَدْ رَأَيْتُنَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَطْعَمَنَا الْخُبْزَ ‏ ‏وَاللَّحْمَ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏حِينَ عَرَفْتُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَهَا ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏فِي حَدِيثِهِ لَقَدْ رَأَيْتُنَا حِينَ أُدْخِلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُطْعِمْنَا الْخُبْزَ وَاللَّحْمَ ‏ ‏فَخَرَجَ النَّاسُ وَبَقِيَ رِجَالٌ يَتَحَدَّثُونَ فِي الْبَيْتِ بَعْدَ الطَّعَامِ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاتَّبَعْتُهُ فَجَعَلَ يَتَتَبَّعُ حُجَرَ نِسَائِهِ فَجَعَلَ يُسَلِّمُ عَلَيْهِنَّ وَيَقُلْنَ يَا رَسُولَ اللَّهِ كَيْفَ وَجَدْتَ أَهْلَكَ ‏ ‏قَالَ فَمَا أَدْرِي أَنَا أَخْبَرْتُهُ أَنَّ الْقَوْمَ قَدْ خَرَجُوا أَوْ أُخْبِرَ ‏ ‏قَالَ فَانْطَلَقَ حَتَّى دَخَلَ الْبَيْتَ فَذَهَبْتُ أَدْخُلُ مَعَهُ فَأَلْقَى السِّتْرَ بَيْنِي وَبَيْنَهُ وَنَزَلَ الْحِجَابُ قَالَ وَوُعِظَ الْقَوْمُ بِمَا وُعِظُوا بِهِ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏فِي حَدِيثِهِ ‏ { ‏لَا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ ‏} { ‏وَلَا مُسْتَأْنِسِينَ لِحَدِيثٍ إِنَّ ذَلِكُمْ كَانَ ‏ ‏يُؤْذِي النَّبِيَّ ‏ ‏فَيَسْتَحْيِي مِنْكُمْ وَاللَّهُ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ ‏}","","",""],[12555,12555,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَاتَ ابْنٌ ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏مِنْ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فَقَالَتْ لِأَهْلِهَا لَا تُحَدِّثُوا ‏ ‏أَبَا طَلْحَةَ ‏ ‏بِابْنِهِ حَتَّى أَكُونَ أَنَا أُحَدِّثُهُ قَالَ فَجَاءَ فَقَرَّبَتْ إِلَيْهِ عَشَاءً فَأَكَلَ وَشَرِبَ قَالَ ثُمَّ تَصَنَّعَتْ لَهُ أَحْسَنَ مَا كَانَتْ ‏ ‏تَصَنَّعُ قَبْلَ ذَلِكَ ‏ ‏فَوَقَعَ ‏ ‏بِهَا فَلَمَّا رَأَتْ أَنَّهُ قَدْ شَبِعَ وَأَصَابَ مِنْهَا قَالَتْ يَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏أَرَأَيْتَ أَنَّ قَوْمًا أَعَارُوا ‏ ‏عَارِيَتَهُمْ ‏ ‏أَهْلَ بَيْتٍ وَطَلَبُوا ‏ ‏عَارِيَتَهُمْ ‏ ‏أَلَهُمْ أَنْ يَمْنَعُوهُمْ قَالَ لَا قَالَتْ فَاحْتَسِبْ ابْنَكَ فَانْطَلَقَ حَتَّى أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ بِمَا كَانَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَارَكَ اللَّهُ لَكُمَا فِي ‏ ‏غَابِرِ ‏ ‏لَيْلَتِكُمَا قَالَ فَحَمَلَتْ قَالَ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ وَهِيَ مَعَهُ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى ‏ ‏الْمَدِينَةَ ‏ ‏مِنْ سَفَرٍ لَا ‏ ‏يَطْرُقُهَا ‏ ‏طُرُوقًا ‏ ‏فَدَنَوْا ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَضَرَبَهَا ‏ ‏الْمَخَاضُ ‏ ‏وَاحْتَبَسَ عَلَيْهَا ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَانْطَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا رَبِّ إِنَّكَ لَتَعْلَمُ أَنَّهُ يُعْجِبُنِي أَنْ أَخْرُجَ مَعَ رَسُولِكَ إِذَا خَرَجَ وَأَدْخُلَ مَعَهُ إِذَا دَخَلَ وَقَدْ احْتَبَسْتُ بِمَا ‏ ‏تَرَى قَالَ تَقُولُ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏يَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏مَا أَجِدُ الَّذِي كُنْتُ أَجِدُ فَانْطَلَقْنَا قَالَ وَضَرَبَهَا ‏ ‏الْمَخَاضُ ‏ ‏حِينَ قَدِمُوا فَوَلَدَتْ غُلَامًا فَقَالَتْ لِي أُمِّي يَا ‏ ‏أَنَسُ ‏ ‏لَا يُرْضِعَنَّهُ أَحَدٌ حَتَّى تَغْدُوَ بِهِ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا أَصْبَحْتُ احْتَمَلْتُهُ وَانْطَلَقْتُ بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَصَادَفْتُهُ وَمَعَهُ ‏ ‏مِيْسَمٌ ‏ ‏فَلَمَّا رَآنِي قَالَ ‏ ‏لَعَلَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَلَدَتْ قُلْتُ نَعَمْ قَالَ فَوَضَعَ ‏ ‏الْمِيسَمَ ‏ ‏قَالَ فَجِئْتُ بِهِ فَوَضَعْتُهُ فِي حِجْرِهِ قَالَ وَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَجْوَةٍ مِنْ عَجْوَةِ ‏ ‏الْمَدِينَةِ ‏ ‏فَلَاكَهَا ‏ ‏فِي ‏ ‏فِيهِ حَتَّى ذَابَتْ ثُمَّ قَذَفَهَا فِي ‏ ‏فِي الصَّبِيِّ فَجَعَلَ الصَّبِيُّ ‏ ‏يَتَلَمَّظُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْظُرُوا إِلَى حُبِّ ‏ ‏الْأَنْصَارِ ‏ ‏التَّمْرَ قَالَ فَمَسَحَ وَجْهَهُ وَسَمَّاهُ ‏ ‏عَبْدَ اللَّهِ ‏","","",""],[12556,12556,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَاصِمُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ ‏ ‏عَلَى شَيْءٍ قَطُّ مَا ‏ ‏وَجَدَ ‏ ‏عَلَى أَصْحَابِ ‏ ‏بِئْرِ مَعُونَةَ ‏ ‏أَصْحَابِ ‏ ‏سَرِيَّةِ ‏ ‏الْمُنْذِرِ بْنِ عَمْرٍو ‏ ‏فَمَكَثَ شَهْرًا يَدْعُو عَلَى الَّذِينَ أَصَابُوهُمْ فِي ‏ ‏قُنُوتِ ‏ ‏صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏يَدْعُو عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏وَلِحْيَانَ ‏ ‏وَهُمْ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏","","",""],[12557,12557,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏الِاثْنَيْنِ ‏ ‏كَشَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتْرَ الْحُجْرَةِ فَرَأَى ‏ ‏أَبَا بَكْرٍ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي بِالنَّاسِ قَالَ فَنَظَرْتُ إِلَى وَجْهِهِ كَأَنَّهُ وَرَقَةُ مُصْحَفٍ وَهُوَ يَتَبَسَّمُ قَالَ وَكِدْنَا أَنْ نُفْتَتَنَ فِي صَلَاتِنَا فَرَحًا لِرُؤْيَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرَادَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَنْ يَنْكُصَ فَأَشَارَ إِلَيْهِ أَنْ كَمَا أَنْتَ ثُمَّ أَرْخَى السِّتْرَ فَقُبِضَ مِنْ يَوْمِهِ ذَلِكَ فَقَامَ ‏ ‏عُمَرُ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَمُتْ وَلَكِنَّ رَبَّهُ أَرْسَلَ إِلَيْهِ كَمَا أَرْسَلَ إِلَى ‏ ‏مُوسَى ‏ ‏فَمَكَثَ عَنْ قَوْمِهِ أَرْبَعِينَ لَيْلَةً وَاللَّهِ إِنِّي لَأَرْجُو أَنْ يَعِيشَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى يَقْطَعَ أَيْدِي رِجَالٍ مِنْ الْمُنَافِقِينَ وَأَلْسِنَتَهُمْ يَزْعُمُونَ ‏ ‏أَوْ قَالَ يَقُولُونَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ مَاتَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏وَكَانَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَدَمَهُ ‏ ‏وَصَحِبَهُ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏كَانَ ‏ ‏يُصَلِّي لَهُمْ فِي وَجَعِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي تُوُفِّيَ فِيهِ حَتَّى إِذَا كَانَ يَوْمُ ‏ ‏الِاثْنَيْنِ فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏كَانَ ‏ ‏يُصَلِّي بِهِمْ فِي وَجَعِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي تُوُفِّيَ فِيهِ كَانَ يَوْمُ ‏ ‏الِاثْنَيْنِ وَهُمْ صُفُوفٌ إِلَى الصَّلَاةِ قَالَ كَشَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتْرَ الْحُجْرَةِ فَذَكَرَ مَعْنَاهُ ‏","","",""],[12558,12558,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏فَاطِمَةَ ‏ ‏بَكَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏يَا أَبَتَاهُ مِنْ رَبِّهِ مَا أَدْنَاهُ يَا أَبَتَاهُ إِلَى ‏ ‏جِبْرِيلَ ‏ ‏يَنْعَاهُ يَا أَبَتَاهُ جَنَّةُ الْفِرْدَوْسِ مَأْوَاهُ ‏","","",""],[12559,12559,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى النِّسَاءِ حِينَ ‏ ‏بَايَعَهُنَّ ‏ ‏أَنْ لَا ‏ ‏يَنُحْنَ ‏ ‏فَقُلْنَ يَا رَسُولَ اللَّهِ إِنَّ نِسَاءً ‏ ‏أَسْعَدْنَنَا ‏ ‏فِي الْجَاهِلِيَّةِ ‏ ‏أَفَنُسْعِدُهُنَّ ‏ ‏فِي الْإِسْلَامِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏إِسْعَادَ ‏ ‏فِي الْإِسْلَامِ وَلَا ‏ ‏شِغَارَ ‏ ‏وَلَا ‏ ‏عَقْرَ ‏ ‏فِي الْإِسْلَامِ وَلَا ‏ ‏جَلَبَ ‏ ‏فِي الْإِسْلَامِ وَلَا ‏ ‏جَنَبَ ‏ ‏وَمَنْ ‏ ‏انْتَهَبَ ‏ ‏فَلَيْسَ مِنَّا ‏","","",""],[12560,12560,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَلِكَ فِي السَّحَرِ يَا ‏ ‏أَنَسُ ‏ ‏إِنِّي أُرِيدُ الصِّيَامَ فَأَطْعِمْنِي شَيْئًا قَالَ فَجِئْتُهُ بِتَمْرٍ وَإِنَاءٍ فِيهِ مَاءٌ بَعْدَ مَا أَذَّنَ ‏ ‏بِلَالٌ ‏ ‏فَقَالَ يَا ‏ ‏أَنَسُ ‏ ‏انْظُرْ إِنْسَانًا يَأْكُلُ مَعِي قَالَ فَدَعَوْتُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي شَرِبْتُ شَرْبَةَ ‏ ‏سَوِيقٍ ‏ ‏وَأَنَا أُرِيدُ الصِّيَامَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أُرِيدُ الصِّيَامَ فَتَسَحَّرَ مَعَهُ وَصَلَّى رَكْعَتَيْنِ ثُمَّ خَرَجَ فَأُقِيمَتْ الصَّلَاةُ ‏","","",""],[12561,12561,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ثَابِتٍ ‏ ‏عَنِ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏خَدَمْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرَ سِنِينَ لَا وَاللَّهِ مَا سَبَّنِي سَبَّةً قَطُّ وَلَا قَالَ لِي أُفٍّ قَطُّ وَلَا قَالَ لِي لِشَيْءٍ فَعَلْتُهُ لِمَ فَعَلْتَهُ وَلَا لِشَيْءٍ لَمْ أَفْعَلْهُ أَلَّا فَعَلْتَهُ ‏","","",""],[12562,12562,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏نَزَلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ ‏} ‏مَرْجِعَنَا مِنْ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ أُنْزِلَتْ عَلَيَّ آيَةٌ أَحَبُّ إِلَيَّ مِمَّا عَلَى الْأَرْضِ ثُمَّ قَرَأَهَا عَلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا هَنِيئًا ‏ ‏مَرِيئًا ‏ ‏يَا رَسُولَ اللَّهِ لَقَدْ بَيَّنَ اللَّهُ عَزَّ وَجَلَّ لَكَ مَاذَا يَفْعَلُ بِكَ فَمَاذَا يَفْعَلُ بِنَا فَنَزَلَتْ عَلَيْهِمْ ‏ { ‏لِيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ ‏ ‏حَتَّى بَلَغَ ‏ ‏فَوْزًا عَظِيمًا ‏}","","",""],[12563,12563,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَكُونُ فِي أُمَّتِي اخْتِلَافٌ وَفُرْقَةٌ يَخْرُجُ مِنْهُمْ قَوْمٌ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏سِيمَاهُمْ ‏ ‏الْحَلْقُ ‏ ‏وَالتَّسْبِيتُ فَإِذَا رَأَيْتُمُوهُمْ ‏ ‏فَأَنِيمُوهُمْ ‏ ‏التَّسْبِيتُ ‏ ‏يَعْنِي اسْتِئْصَالَ الشَّعْرِ الْقَصِيرِ ‏","","",""],[12564,12564,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَلَا أُصَلِّي لَكُمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى بِهِمْ صَلَاةً حَسَنَةً لَمْ يُطَوِّلْ فِيهَا ‏","","",""],[12565,12565,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي دَارِنَا فَحُلِبَ لَهُ ‏ ‏دَاجِنٌ ‏ ‏فَشَابُوا ‏ ‏لَبَنَهَا بِمَاءِ الدَّارِ ثُمَّ نَاوَلُوهُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَرِبَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏عَنْ يَسَارِهِ وَأَعْرَابِيٌّ عَنْ يَمِينِهِ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَعْطِ ‏ ‏أَبَا بَكْرٍ ‏ ‏عِنْدَكَ وَخَشِيَ أَنْ يُعْطِيَهُ الْأَعْرَابِيَّ قَالَ ‏ ‏فَأَعْطَاهُ الْأَعْرَابِيَّ ثُمَّ قَالَ الْأَيْمَنَ فَالْأَيْمَنَ ‏","","",""],[12566,12566,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مُرَّ بِجِنَازَةٍ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَثْنُوا عَلَيْهَا فَقَالُوا كَانَ مَا عَلِمْنَا يُحِبُّ اللَّهَ وَرَسُولَهُ وَأَثْنَوْا عَلَيْهِ خَيْرًا فَقَالَ وَجَبَتْ ثُمَّ مُرَّ عَلَيْهِ بِجِنَازَةٍ أُخْرَى فَقَالَ أَثْنُوا عَلَيْهَا فَقَالُوا بِئْسَ الْمَرْءُ كَانَ فِي دِينِ اللَّهِ فَقَالَ ‏ ‏وَجَبَتْ أَنْتُمْ شُهَدَاءُ اللَّهِ فِي الْأَرْضِ ‏","","",""],[12567,12567,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مَرْوَانَ ‏ ‏مَوْلَى ‏ ‏هِنْدِ ابْنَةِ الْمُهَلَّبِ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏أَرْسَلَتْنِي ‏ ‏هِنْدٌ ‏ ‏إِلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏وَلَمْ يَقُلْ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَسَمِعْتُهُ يُحَدِّثُ أَصْحَابَهُ أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْوِصَالِ ‏","","",""],[12568,12568,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَيُّوبَ الْإِفْرِيقِيُّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏مَنْ تَفَرَّدَ بِدَمِ رَجُلٍ فَقَتَلَهُ فَلَهُ ‏ ‏سَلَبُهُ ‏ ‏قَالَ ‏ ‏فَجَاءَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏بِسَلَبِ أَحَدٍ وَعِشْرِينَ رَجُلًا ‏","","",""],[12569,12569,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏يُضْحِكُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَلَمْ تَرَ إِلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏مُتَقَلِّدَةً ‏ ‏خِنْجَرًا فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَصْنَعِينَ بِهِ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ أَرَدْتُ إِنْ دَنَا مِنِّي أَحَدٌ مِنْهُمْ طَعَنْتُهُ بِهِ ‏","","",""],[12570,12570,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏هِلَالُ بْنُ سُوَيْدٍ أَبُو مُعَلَّى ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏وَهُوَ ‏ ‏يَقُولُ ‏ ‏أُهْدِيَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةُ ‏ ‏طَوَائِرَ فَأَطْعَمَ خَادِمَهُ طَائِرًا فَلَمَّا كَانَ مِنْ الْغَدِ أَتَتْهُ بِهِ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ أَنْهَكِ أَنْ تَرْفَعِي شَيْئًا فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَأْتِي بِرِزْقِ كُلِّ غَدٍ ‏","","",""],[12571,12571,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ بْنُ عَبْدِ اللَّهِ السَّدُوسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَحَدُنَا يَلْقَى صَدِيقَهُ أَيَنْحَنِي لَهُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا قَالَ فَيَلْتَزِمُهُ وَيُقَبِّلُهُ قَالَ لَا قَالَ ‏ ‏فَيُصَافِحُهُ قَالَ نَعَمْ إِنْ شَاءَ ‏","","",""],[12572,12572,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو قِلَابَةَ الْجَرْمِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِيَةُ ‏ ‏نَفَرٍ ‏ ‏مِنْ ‏ ‏عُكْلٍ ‏ ‏فَأَسْلَمُوا ‏ ‏فَاجْتَوَوْا ‏ ‏الْمَدِينَةَ ‏ ‏فَأَمَرَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَأْتُوا إِبِلَ ‏ ‏الصَّدَقَةِ ‏ ‏فَيَشْرَبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا فَفَعَلُوا فَصَحُّوا فَارْتَدُّوا وَقَتَلُوا رُعَاتَهَا ‏ ‏أَوْ رِعَاءَهَا ‏ ‏وَسَاقُوهَا فَبَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَلَبِهِمْ ‏ ‏قَافَةً ‏ ‏فَأُتِيَ بِهِمْ فَقَطَّعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ وَلَمْ ‏ ‏يَحْسِمْهُمْ ‏ ‏حَتَّى مَاتُوا ‏ ‏وَسَمَلَ ‏ ‏أَعْيُنَهُمْ ‏","","",""],[12573,12573,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ حَدَّثَهُمْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَادَ أَنْ يَكْتُبَ إِلَى ‏ ‏الْأَعَاجِمِ ‏ ‏فَقِيلَ إِنَّهُمْ لَا يَقْبَلُونَ كِتَابًا إِلَّا بِنَقْشٍ ‏ ‏فَاتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ فِضَّةٍ وَنَقَشَ فِيهِ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏","","",""],[12574,12574,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ وَاقِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَابِتٌ الْبُنَانِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏قَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ مَا قَدَّمْتَ لَهَا قَالَ حُبَّ اللَّهِ وَرَسُولِهِ قَالَ ‏ ‏أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[12575,12575,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ مَسْعَدَةَ الْبَاهِلِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَسْتَقِيمُ إِيمَانُ عَبْدٍ حَتَّى يَسْتَقِيمَ قَلْبُهُ وَلَا يَسْتَقِيمُ قَلْبُهُ حَتَّى يَسْتَقِيمَ لِسَانُهُ وَلَا يَدْخُلُ رَجُلٌ الْجَنَّةَ لَا يَأْمَنُ جَارُهُ ‏ ‏بَوَائِقَهُ ‏","","",""],[12576,12576,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ مَسْعَدَةَ الْبَاهِلِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ ابْنِ ‏ ‏آدَمَ ‏ ‏خَطَّاءٌ فَخَيْرُ الْخَطَّائِينَ التَّوَّابُونَ وَلَوْ أَنَّ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيَيْنِ مِنْ مَالٍ ‏ ‏لَابْتَغَى ‏ ‏لَهُمَا ثَالِثًا وَلَا يَمْلَأُ جَوْفَ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا التُّرَابُ ‏","","",""],[12577,12577,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَرِيرُ بْنُ حَازِمٍ الْأَزْدِيُّ أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ قِرَاءَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ ‏ ‏مَدًّا ‏","","",""],[12578,12578,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ وَهُوَ أَبُو أَحْمَدَ الطَّالَقَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَكْحُولًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُوسَى بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمْ يَبْلُغْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الشَّيْبِ مَا ‏ ‏يَخْضِبُ ‏ ‏وَلَكِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏كَانَ ‏ ‏يَخْضِبُ ‏ ‏بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏ ‏حَتَّى ‏ ‏يَقْنَأَ ‏ ‏شَعَرُهُ ‏","","",""],[12579,12579,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ حَمْزَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ أَبُو الرَّبِيعِ ‏ ‏إِمَامُ مَسْجِدِ ‏ ‏سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا الدِّينَ مَتِينٌ فَأَوْغِلُوا فِيهِ بِرِفْقٍ ‏","","",""],[12580,12580,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى بْنُ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبَاغَضُوا وَلَا تَقَاطَعُوا وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثَةِ أَيَّامٍ ‏","","",""],[12581,12581,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنِ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏أَشْبَهَهُمْ وَجْهًا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12582,12582,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏تَرَى الْمَرْأَةُ مَا يَرَى الرَّجُلُ فِي مَنَامِهَا فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَتْ مَا يَرَى الرَّجُلُ ‏ ‏يَعْنِي ‏ ‏الْمَاءَ ‏ ‏فَلْتَغْتَسِلْ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏أَوَيَكُونُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ ‏ ‏مَاءُ ‏ ‏الرَّجُلِ غَلِيظٌ أَبْيَضُ وَمَاءُ الْمَرْأَةِ رَقِيقٌ أَصْفَرُ فَمِنْ أَيِّهِمَا سَبَقَ ‏ ‏أَوْ عَلَا ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏نَحْنُ نَشُكُّ يَكُونُ الشَّبَهُ ‏","","",""],[12583,12583,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ فَإِذَا شَهِدُوا وَاسْتَقْبَلُوا قِبْلَتَنَا وَأَكَلُوا ذَبِيحَتَنَا وَصَلَّوْا صَلَاتَنَا فَقَدْ حَرُمَتْ عَلَيْنَا دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا لَهُمْ مَا لِلْمُسْلِمِينَ وَعَلَيْهِمْ مَا عَلَيْهِمْ ‏","","",""],[12584,12584,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ أَبُو عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏سَلَّامٍ أَبِي الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُبِّبَ إِلَيَّ النِّسَاءُ وَالطِّيبُ وَجُعِلَ ‏ ‏قُرَّةُ ‏ ‏عَيْنِي فِي الصَّلَاةِ ‏","","",""],[12585,12585,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ أَبُو عُبَيْدَةَ الْحَدَّادُ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ جَابِرٍ يَعْنِي اللَّقِيطِيَّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُوسَى بْنُ أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏إِذَا قَامَ الْمُؤَذِّنُ فَأَذَّنَ صَلَاةَ الْمَغْرِبِ فِي مَسْجِدٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَامَ مَنْ شَاءَ فَصَلَّى حَتَّى تُقَامَ الصَّلَاةُ وَمَنْ شَاءَ رَكَعَ رَكْعَتَيْنِ ثُمَّ قَعَدَ وَذَلِكَ بِعَيْنَيْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12586,12586,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي الْمَغْرِبَ مَعَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَنْطَلِقُ الرَّجُلُ إِلَى ‏ ‏بَنِي سَلِمَةَ ‏ ‏وَهُوَ يَرَى مَوْقِعَ سَهْمِهِ ‏","","",""],[12587,12587,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَخَرَجَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَرَضَ لَهُ رَجُلٌ ‏ ‏فَحَبَسَهُ ‏ ‏حَتَّى كَادَ بَعْضُ الْقَوْمِ أَنْ يَنْعَسَ ‏","","",""],[12588,12588,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَلْمٍ الْعَلَوِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ يَا بُنَيَّ ‏","","",""],[12589,12589,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَجَرَ عَنْ الشُّرْبِ قَائِمًا ‏ ‏قَالَ ‏ ‏فَقِيلَ ‏ ‏لِأَنَسٍ ‏ ‏فَالْأَكْلُ قَالَ ‏ ‏ذَاكَ أَشَدُّ ‏ ‏أَوْ أَشَرُّ ‏","","",""],[12590,12590,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏عَاصِمٌ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏أَحَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏قَالَ ‏ ‏نَعَمْ هِيَ حَرَامٌ حَرَّمَهَا اللَّهُ وَرَسُولُهُ لَا يُخْتَلَى خَلَاهَا فَمَنْ فَعَلَ ذَلِكَ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ‏","","",""],[12591,12591,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ أَنْ يَلِيَهُ ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَالْأَنْصَارُ ‏ ‏فِي الصَّلَاةِ لِيَأْخُذُوا عَنْهُ ‏","","",""],[12592,12592,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ذَاتَ لَيْلَةٍ ‏ ‏يُصَلِّي فِي حُجْرَتِهِ فَجَاءَ أُنَاسٌ مِنْ أَصْحَابِهِ فَصَلَّوْا بِصَلَاتِهِ فَخَفَّفَ ثُمَّ دَخَلَ الْبَيْتَ ثُمَّ خَرَجَ فَفَعَلَ ذَلِكَ مِرَارًا كُلُّ ذَلِكَ ‏ ‏يُصَلِّي وَيَنْصَرِفُ فَلَمَّا أَصْبَحَ قَالُوا يَا رَسُولَ اللَّهِ صَلَّيْنَا مَعَكَ الْبَارِحَةَ وَنَحْنُ نُحِبُّ أَنْ تَمُدَّ فِي صَلَاتِكَ فَقَالَ ‏ ‏قَدْ عَلِمْتُ بِمَكَانِكُمْ وَعَمْدًا فَعَلْتُ ذَلِكَ ‏","","",""],[12593,12593,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي ‏ ‏قِبْلَةِ الْمَسْجِدِ فَحَكَّهَا فَرُئِيَ فِي وَجْهِهِ ‏ ‏شِدَّةُ ‏ ‏ذَلِكَ عَلَيْهِ فَقَالَ ‏ ‏إِنَّ الْعَبْدَ إِذَا قَامَ ‏ ‏يُصَلِّي فَإِنَّمَا ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ عَزَّ وَجَلَّ فِيمَا بَيْنَهُ وَبَيْنَ الْقِبْلَةِ فَإِذَا بَصَقَ أَحَدُكُمْ فَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى أَوْ يَفْعَلْ هَكَذَا وَأَخَذَ طَرَفَ رِدَائِهِ فَبَصَقَ فِيهِ ثُمَّ دَلَكَ بَعْضَهُ بِبَعْضٍ ‏","","",""],[12594,12594,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏أَخَذَتْ بِيَدِهِ مَقْدَمَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ هَذَا ‏ ‏أَنَسٌ ‏ ‏ابْنِي وَهُوَ غُلَامٌ ‏ ‏كَاتِبٌ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَخَدَمْتُهُ تِسْعَ سِنِينَ ‏ ‏فَمَا قَالَ لِي لِشَيْءٍ صَنَعْتُهُ أَسَأْتَ أَوْ بِئْسَمَا صَنَعْتَ ‏","","",""],[12595,12595,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏وَالْأَنْصَارِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنْ كَانَ يُعْجِبُنَا الرَّجُلُ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏يَجِيءُ فَيَسْأَلُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَجَاءَ ‏ ‏أَعْرَابِيٌّ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ وَأُقِيمَتْ الصَّلَاةُ فَنَهَضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى فَلَمَّا قَضَى الصَّلَاةَ قَالَ أَيْنَ السَّائِلُ عَنْ السَّاعَةِ فَقَامَ الرَّجُلُ فَقَالَ أَنَا فَقَالَ وَمَا أَعْدَدْتَ لَهَا قَالَ مَا أَعْدَدْتُ لَهَا مِنْ كَثِيرِ صَلَاةٍ وَلَا صِيَامٍ إِلَّا أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ قَالَ فَمَا رَأَيْتُ الْمُسْلِمِينَ فَرِحُوا بِشَيْءٍ بَعْدَ الْإِسْلَامِ فَرَحَهُمْ بِذَلِكَ ‏ ‏وَقَالَ ‏ ‏الْأَنْصَارِيُّ ‏ ‏مِنْ كَثِيرِ عَمَلٍ صَلَاةٍ وَلَا صَوْمٍ ‏","","",""],[12596,12596,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏سُئِلَ هَلْ اصْطَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا قَالَ نَعَمْ أَخَّرَ لَيْلَةً الصَّلَاةَ صَلَاةَ الْعِشَاءِ إِلَى ‏ ‏شَطْرِ ‏ ‏اللَّيْلِ ثُمَّ صَلَّى فَلَمَّا صَلَّى أَقْبَلَ بِوَجْهِهِ فَقَالَ ‏ ‏إِنَّ النَّاسَ قَدْ صَلَّوْا وَنَامُوا وَإِنَّكُمْ لَمْ تَزَالُوا فِي صَلَاةٍ مُنْذُ انْتَظَرْتُمْ الصَّلَاةَ قَالَ فَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏خَاتَمِهِ ‏","","",""],[12597,12597,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاصَلَ ‏ ‏فِي آخِرِ الشَّهْرِ ‏ ‏فَوَاصَلَ ‏ ‏نَاسٌ مِنْ النَّاسِ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَوْ مُدَّ لَنَا الشَّهْرُ ‏ ‏لَوَاصَلْتُ ‏ ‏وِصَالًا ‏ ‏يَدَعُ الْمُتَعَمِّقُونَ تَعَمُّقَهُمْ إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي ‏","","",""],[12598,12598,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْفَكَّتْ قَدَمُهُ فَقَعَدَ فِي ‏ ‏مَشْرُبَةٍ ‏ ‏لَهُ دَرَجَتُهَا مِنْ جُذُوعٍ ‏ ‏وَآلَى ‏ ‏مِنْ نِسَائِهِ شَهْرًا فَأَتَاهُ أَصْحَابُهُ ‏ ‏يَعُودُونَهُ ‏ ‏فَصَلَّى بِهِمْ قَاعِدًا وَهُمْ قِيَامٌ فَلَمَّا حَضَرَتْ الصَّلَاةُ الْأُخْرَى قَالَ لَهُمْ ‏ ‏ائْتَمُّوا بِإِمَامِكُمْ فَإِذَا صَلَّى قَائِمًا فَصَلُّوا قِيَامًا وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا مَعَهُ قُعُودًا قَالَ وَنَزَلَ فِي تِسْعٍ وَعِشْرِينَ قَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ ‏ ‏آلَيْتَ ‏ ‏شَهْرًا قَالَ الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏","","",""],[12599,12599,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونٍَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَوْلَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِزَيْنَبَ ‏ ‏فَأَشْبَعَ الْمُسْلِمِينَ خُبْزًا وَلَحْمًا ثُمَّ خَرَجَ كَمَا كَانَ يَصْنَعُ إِذَا تَزَوَّجَ فَيَأْتِي ‏ ‏حُجَرَ ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ فَيُسَلِّمُ عَلَيْهِنَّ وَيَدْعُو لَهُنَّ وَيُسَلِّمْنَ عَلَيْهِ وَيَدْعُونَ لَهُ ثُمَّ رَجَعَ وَأَنَا مَعَهُ فَلَمَّا انْتَهَى إِلَى الْبَابِ إِذَا رَجُلَانِ قَدْ جَرَى بَيْنَهُمَا الْحَدِيثُ فِي نَاحِيَةِ الْبَيْتِ فَلَمَّا أَبْصَرَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْصَرَفَ فَلَمَّا رَأَى الرَّجُلَانِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ رَجَعَ ‏ ‏وَثَبَا ‏ ‏فَزِعَيْنِ فَخَرَجَا ‏ ‏فَلَا أَدْرِي أَنَا أَخْبَرْتُهُ أَوْ مَنْ أَخْبَرَهُ ‏ ‏فَرَجَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12600,12600,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَقَارِبَةً ‏ ‏وَأَبُو بَكْرٍ ‏ ‏حَتَّى كَانَ ‏ ‏عُمَرُ ‏ ‏فَمَدَّ فِي صَلَاةِ ‏ ‏الْغَدَاةِ ‏","","",""]];
